'use strict';
let S={projects:[],tasks:[],checklist:[],milestones:[],attachments:[],activity:[],phases:[],costs:[],issues:[],baselines:[],inbox:[],notifications:[],meetings:[],changes:[],report_snapshots:[],saved_views:[],automation_rules:[],report_revisions:[],recurring_projects:[],decisions:[],procurement:[],field_reports:[],project_templates:[],approvals:[]},csrf='',page='dashboard',projectId=null,tab='board',month=new Date(),ganttMonth=new Date(),editingTask=null;
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iso=d=>{let y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`},today=()=>iso(new Date()),P=id=>S.projects.find(p=>p.id===id),T=id=>S.tasks.find(t=>t.id===id);
const fmt=v=>Number(v||0).toLocaleString(undefined,{style:'currency',currency:'CAD'});
async function api(path,method='GET',data){let opts={method,headers:{'X-CSRF-Token':csrf}};if(data!==undefined){if(data instanceof FormData)opts.body=data;else{opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(data)}}let r=await fetch('/api/'+path,opts);let type=r.headers.get('content-type')||'',x=type.includes('json')?await r.json():null;if(!r.ok)throw Error(x?.error||x?.detail||('Server error ('+r.status+')'));return x}
async function refresh(){S=await api('state');render()}
function toast(s){let el=document.createElement('div');el.className='toast';el.textContent=s;document.body.appendChild(el);setTimeout(()=>el.remove(),2500)}
async function run(f){try{await f()}catch(e){alert(e.message)}}
async function boot(){let s=await api('session?cb='+Date.now());if(!s.authenticated){$('marketing')?.classList.remove('hidden');let n=await api('setup-needed?cb='+Date.now());$('authTitle').textContent=n.needed?'Create administrator':'Sign in';$('authText').textContent=n.needed?'First run: create the administrator account. Choose a password for the administrator account.':'Sign in to your server workspace.';$('authEyebrow').textContent=n.needed?'First-time setup':'Secure workspace';$('authForm').dataset.mode=n.needed?'setup':'login';$('password').minLength=1;return}$('marketing')?.classList.add('hidden');$('auth').classList.add('hidden');$('shell').classList.remove('hidden');csrf=s.csrf;$('who').textContent='Signed in: '+s.username;await refresh()}
$('authForm').onsubmit=async e=>{e.preventDefault();try{let s=await api($('authForm').dataset.mode,'POST',{username:$('username').value,password:$('password').value});csrf=s.csrf;$('marketing')?.classList.add('hidden');$('auth').classList.add('hidden');$('shell').classList.remove('hidden');$('who').textContent='Signed in: '+s.username;await refresh()}catch(err){$('authError').textContent=err.message}};
$('logout').onclick=()=>run(async()=>{await api('logout','POST');location.reload()});
$('nav').onclick=e=>{let b=e.target.closest('[data-page]');if(b){page=b.dataset.page;projectId=null;render()}};
function navActive(){document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page))}
function title(eyebrow,h,sub='',actions=''){return `<div class="top"><div><div class="eyebrow">${eyebrow}</div><h1>${esc(h)}</h1><div class="sub">${esc(sub)}</div></div><div class="actions">${actions}</div></div>`}
function btn(label,fn,cls=''){return `<button class="btn ${cls}" onclick="${fn}">${label}</button>`}
function projectStats(id){let ts=S.tasks.filter(t=>t.project_id===id);return {total:ts.length,done:ts.filter(t=>t.status==='done').length,pct:ts.length?Math.round(ts.filter(t=>t.status==='done').length/ts.length*100):0}}
function taskRow(t){return `<div class="listrow"><div><label><input type="checkbox" ${t.status==='done'?'checked':''} onchange="toggleTask('${t.id}',this.checked)"> <span class="click" onclick="taskDrawer('${t.id}')">${esc(t.name)}</span></label><div class="small muted">${esc(P(t.project_id)?.name||'Personal')} · ${esc(t.due_date||'No due date')}</div></div><span class="pill ${t.priority==='high'?'high':''}">${esc(t.priority)}</span></div>`}
function render(){navActive();if(page==='dashboard')return dashboard();if(page==='projects')return projectId?projectDetail():projects();if(page==='today')return todayView();if(page==='gantt')return ganttView();if(page==='calendar')return calendarView();if(page==='data')return dataView()}
function dashboard(){let active=S.projects.filter(p=>p.status==='active'),open=S.tasks.filter(t=>t.status!=='done'),due=open.filter(t=>t.due_date===today()),over=open.filter(t=>t.due_date&&t.due_date<today());$('main').innerHTML=title('Command center','Overview',new Date().toLocaleDateString(undefined,{dateStyle:'full'}),btn('+ Task','taskModal()')+btn('+ Project','projectModal()','primary'))+`<div class="metrics">${[['Active projects',active.length],['Open tasks',open.length],['Due today',due.length],['Overdue',over.length],['Completed tasks',S.tasks.filter(t=>t.status==='done').length]].map(([k,v])=>`<div class="metric"><strong>${v}</strong><span>${k}</span></div>`).join('')}</div><div class="grid"><div class="panel"><h2>Active projects</h2>${active.slice(0,10).map(p=>`<div class="listrow"><div class="click" onclick="openDetail('${p.id}')"><strong>${esc(p.name)}</strong><div class="small muted">${projectStats(p.id).pct}% complete · ${esc(p.end_date||'No target')}</div></div>${btn('Open',`openDetail('${p.id}')`)}</div>`).join('')||'<div class="empty">Create your first project.</div>'}</div><div class="panel"><h2>Due today</h2>${due.map(taskRow).join('')||'<div class="empty">Nothing due today.</div>'}</div></div>`}
function projects(){let query=window.projectQuery||'';$('main').innerHTML=title('Portfolio','Projects','Create, track, close and archive projects.',btn('+ New project','projectModal()','primary'))+`<div class="toolbar"><input id="projectSearch" placeholder="Search projects..." value="${esc(query)}" oninput="window.projectQuery=this.value;renderProjectList()"></div><div class="panel" id="projectList"></div>`;renderProjectList()}
function renderProjectList(){let q=(window.projectQuery||'').toLowerCase();$('projectList').innerHTML=S.projects.filter(p=>(p.name+' '+p.asset+' '+p.description).toLowerCase().includes(q)).map(p=>`<div class="listrow"><div class="click" onclick="openDetail('${p.id}')"><strong>${esc(p.name)}</strong><div class="small muted">${esc(p.asset||p.description||'No description')} · ${projectStats(p.id).pct}% complete · ${esc(p.status)}</div></div><div class="actions">${btn('Open',`openDetail('${p.id}')`)}${btn('Edit',`projectModal('${p.id}')`)}</div></div>`).join('')||'<div class="empty">No matching projects.</div>'}
function openDetail(id){projectId=id;page='projects';tab='board';render()}
function projectDetail(){let p=P(projectId);if(!p){projectId=null;return projects()}let ts=S.tasks.filter(t=>t.project_id===p.id),st=projectStats(p.id);let actions=btn('← Projects','projectId=null;render()')+btn('+ Task',`taskModal(null,'${p.id}')`,'primary')+btn('Edit project',`projectModal('${p.id}')`)+btn(p.status==='active'?'Close project':'Reopen project',`setProjectStatus('${p.id}','${p.status==='active'?'closed':'active'}')`);let tabs=['board','tasks','milestones','files','notes','meetings','changes','intelligence','history'];$('main').innerHTML=title(p.status,p.name,p.description,actions)+`<div class="metrics"><div class="metric"><strong>${st.pct}%</strong><span>Complete</span></div><div class="metric"><strong>${st.total}</strong><span>Tasks</span></div><div class="metric"><strong>${st.done}</strong><span>Done</span></div><div class="metric"><strong>${fmt(p.estimated_cost)}</strong><span>Estimated</span></div><div class="metric"><strong>${fmt(p.actual_cost)}</strong><span>Actual</span></div></div><div class="statusline">Asset: ${esc(p.asset||'—')} · Contractor: ${esc(p.contractor||'—')} · PO: ${esc(p.po_number||'—')} · Shutdown: ${p.shutdown_required?'Required':'No'} · Commissioning: ${esc(p.commissioning)}</div><div class="tabs">${tabs.map(t=>`<button class="${tab===t?'active':''}" onclick="tab='${t}';render()">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div id="projectPane"></div>`;let pane=$('projectPane');if(tab==='board'){pane.innerHTML=`<div class="kanban">${[['todo','To do'],['doing','In progress'],['done','Done']].map(([status,label])=>`<div class="lane" ondragover="event.preventDefault();this.classList.add('over')" ondragleave="this.classList.remove('over')" ondrop="dropKanban(event,'${status}')"><h3>${label} · ${ts.filter(t=>t.status===status).length}</h3>${ts.filter(t=>t.status===status).map(t=>`<div class="taskcard ${blocked(t)?'blocked':''}" draggable="true" ondragstart="event.dataTransfer.setData('task', '${t.id}')" onclick="taskDrawer('${t.id}')"><strong>${esc(t.name)}</strong><div class="small muted">${esc(t.due_date||'Unscheduled')} · ${esc(t.priority)}${blocked(t)?' · BLOCKED':''}</div></div>`).join('')||'<div class="small muted">Drop tasks here</div>'}</div>`).join('')}</div>`}else if(tab==='tasks'){pane.innerHTML=`<div class="panel">${ts.map(taskRow).join('')||'<div class="empty">No tasks yet.</div>'}</div>`}else if(tab==='milestones'){pane.innerHTML=`<div class="panel"><div class="between"><h2>Project milestones</h2>${btn('+ Milestone','milestoneModal()','primary')}</div>${S.milestones.filter(m=>m.project_id===p.id).map(m=>`<div class="listrow"><label><input type="checkbox" ${m.done?'checked':''} onchange="setMilestone('${m.id}',this.checked)"> ${esc(m.title)} <span class="small muted">${esc(m.due_date||'')}</span></label>${btn('Delete',`removeMilestone('${m.id}')`,'danger')}</div>`).join('')||'<div class="empty">No milestones yet.</div>'}</div>`}else if(tab==='files'){pane.innerHTML=`<div class="panel"><h2>Project documents</h2><input type="file" id="file" onchange="uploadFile(this.files[0], '${p.id}')"><p class="small muted">Up to 20 MB per file. PDFs, drawings, Office documents, images and ZIP files.</p>${filesFor(p.id,null)}</div>`}else if(tab==='notes'){pane.innerHTML=`<div class="panel"><h2>Notes & closeout</h2><label class="small muted">Project notes</label><textarea id="notes" style="width:100%">${esc(p.notes)}</textarea><label class="small muted">Closeout documentation</label><textarea id="closeout" style="width:100%">${esc(p.closeout)}</textarea><p>${btn('Save notes',`saveProjectNotes('${p.id}')`,'primary')}</p></div>`}else{pane.innerHTML=`<div class="panel history"><h2>Activity history</h2>${S.activity.filter(a=>a.project_id===p.id).map(a=>`<div class="listrow"><span>${esc(a.description)}</span><span class="small muted">${esc(a.created_at)}</span></div>`).join('')||'<div class="empty">No activity.</div>'}</div>`}}
function blocked(t){return t.depends_on&&T(t.depends_on)?.status!=='done'}
function dropKanban(e,status){e.preventDefault();e.currentTarget.classList.remove('over');let id=e.dataTransfer.getData('task');if(id)run(async()=>{await api('tasks/'+id,'PATCH',{status});await refresh()})}
function todayView(){let q=window.taskQuery||'';$('main').innerHTML=title('Daily planner','Tasks','Search all tasks and manage your daily to-do list.',btn('+ Task','taskModal()','primary'))+`<div class="toolbar"><input id="taskSearch" placeholder="Search tasks..." value="${esc(q)}" oninput="window.taskQuery=this.value;renderTaskList()"><select id="taskFilter" onchange="window.taskFilter=this.value;renderTaskList()"><option value="today">Due today</option><option value="open">All open</option><option value="all">All tasks</option><option value="overdue">Overdue</option></select></div><div class="panel" id="taskList"></div>`;$('taskFilter').value=window.taskFilter||'today';renderTaskList()}
function renderTaskList(){let q=(window.taskQuery||'').toLowerCase(),f=window.taskFilter||'today';$('taskList').innerHTML=S.tasks.filter(t=>(t.name+' '+t.notes).toLowerCase().includes(q)&&(f==='all'||(f==='today'&&t.due_date===today()&&t.status!=='done')||(f==='open'&&t.status!=='done')||(f==='overdue'&&t.due_date&&t.due_date<today()&&t.status!=='done'))).map(taskRow).join('')||'<div class="empty">No tasks match this filter.</div>'}
function closeModal(){$('modal').classList.add('hidden');$('modalBody').innerHTML=''}
function modal(title,body){$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modal').classList.remove('hidden')}
function val(id){return $(id).value}
function projectModal(id){let p=P(id)||{};modal(id?'Edit project':'New project',`<form class="form" onsubmit="saveProject(event,'${id||''}')"><label class="wide">Project name<input id="p_name" required value="${esc(p.name||'')}"></label><label class="wide">Description<textarea id="p_description">${esc(p.description||'')}</textarea></label><label>Start date<input type="date" id="p_start" value="${esc(p.start_date||today())}"></label><label>Target date<input type="date" id="p_end" value="${esc(p.end_date||today())}"></label><label>Asset / equipment<input id="p_asset" value="${esc(p.asset||'')}"></label><label>Contractor<input id="p_contractor" value="${esc(p.contractor||'')}"></label><label>PO number<input id="p_po" value="${esc(p.po_number||'')}"></label><label>Commissioning<select id="p_commissioning">${['not_started','in_progress','passed','failed'].map(s=>`<option ${p.commissioning===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Estimated cost (CAD)<input type="number" step="0.01" min="0" id="p_est" value="${p.estimated_cost||0}"></label><label>Actual cost (CAD)<input type="number" step="0.01" min="0" id="p_actual" value="${p.actual_cost||0}"></label><label class="wide"><span><input type="checkbox" id="p_shutdown" ${p.shutdown_required?'checked':''}> Shutdown required</span></label><div class="actions wide">${id?btn('Delete project',`deleteProject('${id}')`,'danger'):''}<button class="btn primary" type="submit">Save project</button></div></form>`)}
async function saveProject(e,id){e.preventDefault();await run(async()=>{let data={name:val('p_name'),description:val('p_description'),start_date:val('p_start'),end_date:val('p_end'),asset:val('p_asset'),contractor:val('p_contractor'),po_number:val('p_po'),commissioning:val('p_commissioning'),estimated_cost:val('p_est'),actual_cost:val('p_actual'),shutdown_required:$('p_shutdown').checked};let r=await api(id?'projects/'+id:'projects',id?'PATCH':'POST',data);closeModal();await refresh();openDetail(id||r.id)})}
async function setProjectStatus(id,status){await run(async()=>{await api('projects/'+id,'PATCH',{status});await refresh()})}
async function deleteProject(id){if(!confirm('Delete project and all its tasks, milestones, and files?'))return;await run(async()=>{await api('projects/'+id,'DELETE');closeModal();projectId=null;await refresh()})}
async function saveProjectNotes(id){await run(async()=>{await api('projects/'+id,'PATCH',{notes:val('notes'),closeout:val('closeout')});await refresh();toast('Saved')})}
function taskModal(id,pid){let t=T(id)||{};editingTask=id||null;let ps=S.projects.map(p=>`<option value="${p.id}" ${(t.project_id||pid)===p.id?'selected':''}>${esc(p.name)}</option>`).join('');let deps=S.tasks.filter(x=>x.id!==id).map(x=>`<option value="${x.id}" ${t.depends_on===x.id?'selected':''}>${esc(x.name)}</option>`).join('');modal(id?'Edit task':'New task',`<form class="form" onsubmit="saveTask(event,'${id||''}')"><label class="wide">Task name<input id="t_name" required value="${esc(t.name||'')}"></label><label>Project<select id="t_project"><option value="">Personal / no project</option>${ps}</select></label><label>Priority<select id="t_priority">${['low','medium','high'].map(x=>`<option ${t.priority===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Start date<input type="date" id="t_start" value="${esc(t.start_date||t.due_date||today())}"></label><label>Due date<input type="date" id="t_due" value="${esc(t.due_date||today())}"></label><label>Status<select id="t_status">${['todo','doing','done'].map(x=>`<option value="${x}" ${t.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Repeat<select id="t_recurring">${['','daily','weekdays','weekly'].map(x=>`<option value="${x}" ${t.recurring===x?'selected':''}>${x||'None'}</option>`).join('')}</select></label><label class="wide">Depends on<select id="t_dep"><option value="">No dependency</option>${deps}</select></label><label class="wide">Notes<textarea id="t_notes">${esc(t.notes||'')}</textarea></label><div class="actions wide">${id?btn('Delete task',`deleteTask('${id}')`,'danger'):''}<button type="submit" class="btn primary">Save task</button></div></form>${id?`<hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><h3>Subtask checklist</h3><div id="checkItems">${checklistFor(id)}</div><div class="toolbar"><input id="newCheck" placeholder="New checklist item"><button class="btn" onclick="addCheck('${id}')">Add</button></div><h3>Task attachments</h3><input type="file" onchange="uploadFile(this.files[0],null,'${id}')">${filesFor(null,id)}`:''}`)}
function checklistFor(id){return S.checklist.filter(c=>c.task_id===id).map(c=>`<div class="checkrow"><input type="checkbox" ${c.done?'checked':''} onchange="setCheck('${c.id}',this.checked)"><span>${esc(c.title)}</span>${btn('✕',`removeCheck('${c.id}')`,'danger')}</div>`).join('')||'<div class="small muted">No checklist items.</div>'}
async function saveTask(e,id){e.preventDefault();await run(async()=>{let data={name:val('t_name'),project_id:val('t_project')||null,start_date:val('t_start'),due_date:val('t_due'),priority:val('t_priority'),status:val('t_status'),recurring:val('t_recurring'),depends_on:val('t_dep')||null,notes:val('t_notes')};await api(id?'tasks/'+id:'tasks',id?'PATCH':'POST',data);closeModal();await refresh()})}
async function toggleTask(id,checked){await run(async()=>{await api('tasks/'+id,'PATCH',{status:checked?'done':'todo'});await refresh()})}
async function deleteTask(id){if(!confirm('Delete this task and its checklist?'))return;await run(async()=>{await api('tasks/'+id,'DELETE');closeModal();await refresh()})}
async function addCheck(id){let title=val('newCheck').trim();if(!title)return;await run(async()=>{await api('checklist','POST',{task_id:id,title});await refresh();taskModal(id)})}
async function setCheck(id,done){await run(async()=>{await api('checklist/'+id,'PATCH',{done});await refresh();taskModal(editingTask)})}
async function removeCheck(id){await run(async()=>{await api('checklist/'+id,'DELETE');await refresh();taskModal(editingTask)})}
function milestoneModal(){modal('New milestone',`<form class="form" onsubmit="saveMilestone(event)"><label class="wide">Milestone<input id="m_title" required></label><label>Target date<input id="m_due" type="date" value="${today()}"></label><div class="actions wide"><button class="btn primary">Save milestone</button></div></form>`)}
async function saveMilestone(e){e.preventDefault();await run(async()=>{await api('milestones','POST',{project_id:projectId,title:val('m_title'),due_date:val('m_due')});closeModal();await refresh()})}
async function setMilestone(id,done){await run(async()=>{await api('milestones/'+id,'PATCH',{done});await refresh()})}
async function removeMilestone(id){await run(async()=>{await api('milestones/'+id,'DELETE');await refresh()})}
function filesFor(pid,tid){return S.attachments.filter(a=>tid?a.task_id===tid:(a.project_id===pid&&!a.task_id)).map(a=>`<div class="fileitem"><span>📎 <a href="/api/attachments/${a.id}">${esc(a.original_name)}</a> <span class="small muted">(${Math.round(a.size/1024)} KB)</span></span>${btn('Delete',`deleteFile('${a.id}')`,'danger')}</div>`).join('')||'<p class="small muted">No files uploaded.</p>'}
async function uploadFile(file,pid,tid){if(!file)return;await run(async()=>{let d=new FormData();d.append('file',file);if(pid)d.append('project_id',pid);if(tid)d.append('task_id',tid);await api('attachments','POST',d);await refresh();if(tid)taskModal(tid);toast('File uploaded')})}
async function deleteFile(id){if(!confirm('Delete this file?'))return;await run(async()=>{await api('attachments/'+id,'DELETE');await refresh();if(editingTask&&!$('modal').classList.contains('hidden'))taskModal(editingTask)})}
function projectGantt(pid){
 let p=P(pid);if(!p)return;let dated=S.tasks.filter(t=>t.project_id===pid&&t.due_date),marks=S.milestones.filter(m=>m.project_id===pid&&m.due_date);
 let all=[...dated.map(t=>t.start_date||t.due_date),...dated.map(t=>t.due_date),...marks.map(m=>m.due_date)].filter(Boolean);
 let base=all.length?new Date(all.sort()[0]+'T12:00:00'):new Date(),m=new Date(base.getFullYear(),base.getMonth(),1),end=new Date(m.getFullYear(),m.getMonth()+1,0),days=end.getDate();
 modal(`Project Gantt · ${esc(p.name)}`,`<div class="between"><div><b>${m.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</b><div class="small muted">Only tasks and milestones from this project are shown.</div></div></div><div class="gantt" style="overflow:auto;margin-top:12px"><div id="projectGanttGrid" class="gtable" style="--days:${days};min-width:${220+days*36}px"></div></div>`);
 let items=[...dated.map(t=>({...t,kind:'task',start:t.start_date||t.due_date,end:t.due_date})),...marks.map(t=>({...t,kind:'milestone',start:t.due_date,end:t.due_date}))].filter(t=>t.start<=iso(end)&&t.end>=iso(m)).sort((a,b)=>a.start.localeCompare(b.start));
 let h='<div class="glabel">Task / milestone</div>';for(let d=1;d<=days;d++)h+=`<div class="gdate">${d}</div>`;
 for(let t of items){h+=`<div class="glabel click" onclick="${t.kind==='task'?`closeModal();taskModal('${t.id}')`:''}">${esc(t.name||t.title)}</div>`;let left=Math.max(1,Math.round((new Date(t.start+'T12:00:00')-m)/86400000)+1),right=Math.min(days,Math.round((new Date(t.end+'T12:00:00')-m)/86400000)+1),width=(right-left+1)*36-4;for(let d=1;d<=days;d++)h+=`<div class="gcell">${d===left?`<div class="gbar ${t.kind==='milestone'?'milestone':''}" style="width:${width}px" title="${esc(t.name||t.title)} · ${t.start} to ${t.end}">${t.kind==='task'?esc(t.name):''}</div>`:''}</div>`}
 $('projectGanttGrid').innerHTML=items.length?h:'<div class="empty">This project has no dated tasks or milestones in its first scheduled month.</div>';
}
function ganttView(){let m=new Date(ganttMonth.getFullYear(),ganttMonth.getMonth(),1),end=new Date(m.getFullYear(),m.getMonth()+1,0),days=end.getDate();$('main').innerHTML=title('Timeline','Gantt schedule','Drag task bars horizontally to reschedule. Task bars span start to due date.',btn('← Previous','shiftGantt(-1)')+btn('Today','ganttMonth=new Date();render()')+btn('Next →','shiftGantt(1)'))+`<div class="panel gantt"><div class="between"><h2>${m.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h2><span class="small muted">Drag bars to move dates · diamonds are milestones</span></div><div id="ganttGrid" class="gtable" style="--days:${days}"></div></div>`;let h='<div class="glabel">Task / milestone</div>';for(let d=1;d<=days;d++)h+=`<div class="gdate">${d}</div>`;let items=[...S.tasks.filter(t=>t.due_date).map(t=>({...t,kind:'task',start:t.start_date||t.due_date,end:t.due_date,project:P(t.project_id)?.name||'Personal'})),...S.milestones.filter(t=>t.due_date).map(t=>({...t,kind:'milestone',start:t.due_date,end:t.due_date,project:P(t.project_id)?.name||''}))].filter(t=>t.start<=iso(end)&&t.end>=iso(m)).sort((a,b)=>a.start.localeCompare(b.start));for(let t of items){h+=`<div class="glabel click" onclick="${t.kind==='task'?`taskModal('${t.id}')`:`openDetail('${t.project_id}')`}" title="${esc(t.project)}">${esc(t.name||t.title)}<div class="small muted">${esc(t.project)}</div></div>`;let left=Math.max(1,Math.round((new Date(t.start+'T12:00:00')-m)/86400000)+1),right=Math.min(days,Math.round((new Date(t.end+'T12:00:00')-m)/86400000)+1),width=(right-left+1)*36-4;for(let d=1;d<=days;d++){h+=`<div class="gcell">${d===left?`<div class="gbar ${t.kind==='milestone'?'milestone':''}" style="width:${width}px" ${t.kind==='task'?`draggable="true" ondragstart="ganttDragStart(event,'${t.id}')" ondragend="ganttDragEnd(event,'${t.id}')"`:''} title="${esc(t.name||t.title)} · ${t.start} to ${t.end}">${t.kind==='task'?esc(t.name):''}</div>`:''}</div>`}}$('ganttGrid').innerHTML=h||'<div class="empty">No dated tasks.</div>'}
let dragX=0;function ganttDragStart(e,id){dragX=e.clientX;e.dataTransfer.setData('gantt',id);e.dataTransfer.effectAllowed='move'}function ganttDragEnd(e,id){let delta=Math.round((e.clientX-dragX)/36);if(!delta)return;run(async()=>{let t=T(id),shift=s=>{if(!s)return null;let d=new Date(s+'T12:00:00');d.setDate(d.getDate()+delta);return iso(d)};await api('tasks/'+id,'PATCH',{start_date:shift(t.start_date),due_date:shift(t.due_date)});await refresh();toast('Task rescheduled')})}function shiftGantt(n){ganttMonth.setMonth(ganttMonth.getMonth()+n);render()}
function calendarView(){let m=new Date(month.getFullYear(),month.getMonth(),1),last=new Date(m.getFullYear(),m.getMonth()+1,0),offset=(m.getDay()+6)%7;$('main').innerHTML=title('Schedule','Calendar',m.toLocaleDateString(undefined,{month:'long',year:'numeric'}),btn('←','shiftMonth(-1)')+btn('Today','month=new Date();render()')+btn('→','shiftMonth(1)'))+`<div class="calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="small muted" style="text-align:center">${d}</div>`).join('')}${Array(offset).fill('<div></div>').join('')}${Array.from({length:last.getDate()},(_,i)=>{let d=i+1,key=iso(new Date(m.getFullYear(),m.getMonth(),d));return `<div class="calday ${key===today()?'today':''}"><strong>${d}</strong>${S.tasks.filter(t=>t.due_date===key).map(t=>`<div class="calitem" onclick="taskDrawer('${t.id}')">${esc(t.name)}</div>`).join('')}${S.milestones.filter(t=>t.due_date===key).map(t=>`<div class="calitem" onclick="openDetail('${t.project_id}')">◆ ${esc(t.title)}</div>`).join('')}</div>`}).join('')}</div>`}function shiftMonth(n){month.setMonth(month.getMonth()+n);render()}
function dataView(){$('main').innerHTML=title('Ownership','Data & backup','SQLite is the source of truth on this Windows computer.')+`<div class="grid"><div class="panel"><h2>Import your V3 data</h2><p class="muted">In V3, go to Data → Export JSON Backup. Select that file here to copy projects, tasks, notes and dependencies into V4. Existing V4 data is retained; importing the same file twice creates duplicates.</p><input type="file" id="import" accept=".json,application/json"><p>${btn('Import V3 backup','importV3()','primary')}</p></div><div class="panel"><h2>Export records</h2><p class="muted">Export a JSON snapshot of records. For a complete disaster-recovery backup, also copy the SQLite database and uploads directory from your JWorks data folder.</p><a class="btn" href="/api/export">Download JSON export</a></div></div>`}
async function importV3(){let file=$('import').files[0];if(!file)return alert('Choose your V3 JSON backup.');if(!confirm('Import V3 projects/tasks into your existing V4 workspace?'))return;await run(async()=>{let x=JSON.parse(await file.text()),r=await api('import-v3','POST',x);await refresh();toast(`Imported ${r.projects} projects and ${r.tasks} tasks`)})}
function startJWorks(){boot().catch(e=>{$('authError').textContent=e.message})}
