// ===== JWorks 8.0 enhancements =====
function phaseName(id){return S.phases?.find(x=>x.id===id)?.title||''}
function projectFacts(id){let p=P(id),ts=S.tasks.filter(t=>t.project_id===id),open=ts.filter(t=>t.status!=='done'),over=open.filter(t=>t.due_date&&t.due_date<today()),blockedN=open.filter(blocked),ms=(S.milestones||[]).filter(m=>m.project_id===id),costs=(S.costs||[]).filter(c=>c.project_id===id),spent=costs.filter(c=>c.status==='spent').reduce((a,c)=>a+Number(c.amount||0),0),committed=costs.reduce((a,c)=>a+Number(c.amount||0),0),pct=ts.length?Math.round(ts.filter(t=>t.status==='done').length/ts.length*100):0,days=p?.end_date?Math.ceil((new Date(p.end_date+'T12:00:00')-new Date(today()+'T12:00:00'))/86400000):null;return {ts,open,over,blockedN,ms,costs,spent,committed,pct,days}}

dashboard=function(){let active=S.projects.filter(p=>p.status==='active'),open=S.tasks.filter(t=>t.status!=='done'),due=open.filter(t=>t.due_date===today()),over=open.filter(t=>t.due_date&&t.due_date<today()),blockedAll=open.filter(blocked),attention=active.map(p=>({p,f:projectFacts(p.id)})).filter(x=>x.f.over.length||x.f.blockedN.length||(x.f.days!==null&&x.f.days<=14));$('main').innerHTML=title('Command center','Overview',new Date().toLocaleDateString(undefined,{dateStyle:'full'}),btn('+ Task','taskModal()')+btn('+ Project','projectModal()','primary'))+`<div class="metrics">${[['Active projects',active.length],['Open tasks',open.length],['Due today',due.length],['Overdue',over.length],['Pending Dependency',blockedAll.length]].map(([k,v])=>`<div class="metric"><strong>${v}</strong><span>${k}</span></div>`).join('')}</div><div class="grid"><div class="panel"><h2>Needs attention</h2>${attention.map(({p,f})=>`<div class="listrow attention"><div class="click" onclick="openDetail('${p.id}')"><strong>${esc(p.name)}</strong><div class="small muted">${f.over.length} overdue · ${f.blockedN.length} pending dependenc${f.blockedN.length===1?'y':'ies'}${f.days!==null?' · '+f.days+' days to target':''}</div><div class="progress" style="margin-top:8px"><i style="width:${f.pct}%"></i></div></div>${btn('Open',`openDetail('${p.id}')`)}</div>`).join('')||'<div class="empty">No active project exceptions right now.</div>'}</div><div class="panel"><h2>Due today</h2>${due.map(taskRow).join('')||'<div class="empty">Nothing due today.</div>'}</div></div>`}

projectDetail=function(){let p=P(projectId);if(!p){projectId=null;return projects()}let ts=S.tasks.filter(t=>t.project_id===p.id),f=projectFacts(p.id),actions=btn('← Projects','projectId=null;render()')+btn('Status report',`generateReport('${p.id}')`,'primary')+btn('+ Task',`taskModal(null,'${p.id}')`)+btn('Edit project',`projectModal('${p.id}')`)+btn(p.status==='active'?'Close project':'Reopen project',`setProjectStatus('${p.id}','${p.status==='active'?'closed':'active'}')`),tabs=['board','tasks','phases','milestones','budget','risks','files','notes','history'];$('main').innerHTML=title(p.status,p.name,p.description,actions)+`<div class="metrics"><div class="metric"><strong>${f.pct}%</strong><span>Complete</span></div><div class="metric"><strong>${f.over.length}</strong><span>Overdue</span></div><div class="metric"><strong>${f.blockedN.length}</strong><span>Pending Dependency</span></div><div class="metric"><strong>${fmt(f.committed)}</strong><span>Committed/spent</span></div><div class="metric"><strong>${f.days===null?'—':f.days}</strong><span>Days to target</span></div></div><div class="tabs">${tabs.map(t=>`<button class="${tab===t?'active':''}" onclick="tab='${t}';render()">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div id="projectPane"></div>`;let pane=$('projectPane');
if(tab==='board'){pane.innerHTML=`<div class="kanban">${[['todo','To do'],['doing','In progress'],['done','Done']].map(([status,label])=>`<div class="lane" ondragover="event.preventDefault();this.classList.add('over')" ondragleave="this.classList.remove('over')" ondrop="dropKanban(event,'${status}')"><h3>${label} · ${ts.filter(t=>t.status===status).length}</h3>${ts.filter(t=>t.status===status).map(t=>`<div class="taskcard ${blocked(t)?'blocked':''}" draggable="true" ondragstart="event.dataTransfer.setData('task','${t.id}')" onclick="taskDrawer('${t.id}')"><strong>${esc(t.name)}</strong><div class="small muted">${phaseName(t.phase_id)?esc(phaseName(t.phase_id))+' · ':''}${esc(t.due_date||'Unscheduled')} · ${esc(t.priority)}${blocked(t)?' · BLOCKED':''}</div></div>`).join('')||'<div class="small muted">Drop tasks here</div>'}</div>`).join('')}</div>`}
else if(tab==='tasks'){pane.innerHTML=`<div class="panel">${ts.map(taskRow).join('')||'<div class="empty">No tasks yet.</div>'}</div>`}
else if(tab==='phases'){let ps=(S.phases||[]).filter(x=>x.project_id===p.id).sort((a,b)=>a.sort_order-b.sort_order);pane.innerHTML=`<div class="panel"><div class="between"><h2>Project phases</h2>${btn('+ Phase','phaseModal()','primary')}</div>${ps.map(ph=>{let pts=ts.filter(t=>t.phase_id===ph.id),pc=pts.length?Math.round(pts.filter(t=>t.status==='done').length/pts.length*100):0;return `<div class="phase"><div class="between"><strong>${esc(ph.title)}</strong><div>${btn('Edit',`phaseModal('${ph.id}')`)} ${btn('Delete',`deletePhase('${ph.id}')`,'danger')}</div></div><div class="small muted">${esc(ph.start_date||'')} → ${esc(ph.end_date||'')} · ${pc}% complete · ${pts.length} tasks</div><div class="progress" style="margin-top:8px"><i style="width:${pc}%"></i></div></div>`}).join('')||'<div class="empty">Add phases such as Planning, Execution, Testing and Closeout.</div>'}</div>`}
else if(tab==='milestones'){pane.innerHTML=`<div class="panel"><div class="between"><h2>Project milestones</h2>${btn('+ Milestone','milestoneModal()','primary')}</div>${S.milestones.filter(m=>m.project_id===p.id).map(m=>`<div class="listrow"><label><input type="checkbox" ${m.done?'checked':''} onchange="setMilestone('${m.id}',this.checked)"> ${esc(m.title)} <span class="small muted">${esc(m.due_date||'')}</span></label>${btn('Delete',`removeMilestone('${m.id}')`,'danger')}</div>`).join('')||'<div class="empty">No milestones yet.</div>'}</div>`}
else if(tab==='budget'){pane.innerHTML=`<div class="kpirow"><div class="kpi"><b>Project estimate</b><div>${fmt(p.estimated_cost)}</div></div><div class="kpi"><b>Committed</b><div>${fmt(f.committed)}</div></div><div class="kpi"><b>Spent</b><div>${fmt(f.spent)}</div></div><div class="kpi"><b>Variance vs estimate</b><div>${fmt(Number(p.estimated_cost||0)-f.committed)}</div></div></div><div class="panel" style="margin-top:14px"><div class="between"><h2>Cost entries</h2>${btn('+ Cost','costModal()','primary')}</div>${f.costs.map(c=>`<div class="listrow"><div><strong>${esc(c.title)}</strong><div class="small muted">${esc(c.vendor)} · ${esc(c.po_number)} · ${esc(c.status)} · ${esc(c.cost_date||'')}</div></div><div>${fmt(c.amount)} ${btn('Delete',`deleteCost('${c.id}')`,'danger')}</div></div>`).join('')||'<div class="empty">No cost entries.</div>'}</div>`}
else if(tab==='risks'){let xs=(S.issues||[]).filter(x=>x.project_id===p.id);pane.innerHTML=`<div class="panel"><div class="between"><h2>Risks & issues</h2>${btn('+ Risk / issue','issueModal()','primary')}</div>${xs.map(x=>`<div class="listrow ${x.severity==='high'?'issue-high':''}"><div><strong>${esc(x.title)}</strong><div class="small muted">${esc(x.kind)} · ${esc(x.severity)} · ${esc(x.status)}${x.owner_name?' · '+esc(x.owner_name):''}</div></div><div class="actions">${x.status==='open'?btn('Close',`setIssue('${x.id}','closed')`):btn('Reopen',`setIssue('${x.id}','open')`)}${btn('Delete',`deleteIssue('${x.id}')`,'danger')}</div></div>`).join('')||'<div class="empty">No risks or issues recorded.</div>'}</div>`}
else if(tab==='files'){pane.innerHTML=`<div class="panel"><h2>Project documents</h2><input type="file" onchange="uploadFile(this.files[0],'${p.id}')">${filesFor(p.id,null)}</div>`}
else if(tab==='notes'){pane.innerHTML=`<div class="panel"><h2>Project notes</h2><textarea id="notes" style="width:100%">${esc(p.notes)}</textarea><label class="small muted">Closeout documentation</label><textarea id="closeout" style="width:100%">${esc(p.closeout)}</textarea><p>${btn('Save notes',`saveProjectNotes('${p.id}')`,'primary')}</p></div>`}
else {pane.innerHTML=`<div class="panel history">${S.activity.filter(a=>a.project_id===p.id).map(a=>`<div class="listrow"><span>${esc(a.description)}</span><span class="small muted">${new Date(a.created_at).toLocaleString()}</span></div>`).join('')||'<div class="empty">No activity yet.</div>'}</div>`}}

function phaseModal(id){let x=(S.phases||[]).find(p=>p.id===id)||{};modal(id?'Edit phase':'New phase',`<form class="form" onsubmit="savePhase(event,'${id||''}')"><label class="wide">Phase name<input id="ph_title" required value="${esc(x.title||'')}"></label><label>Start<input id="ph_start" type="date" value="${esc(x.start_date||P(projectId)?.start_date||today())}"></label><label>End<input id="ph_end" type="date" value="${esc(x.end_date||P(projectId)?.end_date||today())}"></label><div class="actions wide"><button class="btn primary">Save phase</button></div></form>`)}
async function savePhase(e,id){e.preventDefault();await run(async()=>{let d={project_id:projectId,title:val('ph_title'),start_date:val('ph_start'),end_date:val('ph_end')};await api(id?'phases/'+id:'phases',id?'PATCH':'POST',d);closeModal();await refresh()})}
async function deletePhase(id){if(!confirm('Delete this phase? Tasks will remain.'))return;await run(async()=>{await api('phases/'+id,'DELETE');await refresh()})}
function costModal(){modal('New cost entry',`<form class="form" onsubmit="saveCost(event)"><label class="wide">Description<input id="c_title" required></label><label>Vendor<input id="c_vendor"></label><label>PO / reference<input id="c_po"></label><label>Amount<input id="c_amount" type="number" min="0" step=".01" required></label><label>Status<select id="c_status"><option>committed</option><option>spent</option></select></label><label>Date<input id="c_date" type="date" value="${today()}"></label><label class="wide">Notes<textarea id="c_notes"></textarea></label><div class="actions wide"><button class="btn primary">Add cost</button></div></form>`)}
async function saveCost(e){e.preventDefault();await run(async()=>{await api('costs','POST',{project_id:projectId,title:val('c_title'),vendor:val('c_vendor'),po_number:val('c_po'),amount:val('c_amount'),status:val('c_status'),cost_date:val('c_date'),notes:val('c_notes')});closeModal();await refresh()})}
async function deleteCost(id){if(!confirm('Delete this cost entry?'))return;await run(async()=>{await api('costs/'+id,'DELETE');await refresh()})}
function issueModal(){modal('New risk / issue',`<form class="form" onsubmit="saveIssue(event)"><label class="wide">Title<input id="i_title" required></label><label>Type<select id="i_kind"><option>risk</option><option>issue</option></select></label><label>Severity<select id="i_severity"><option>low</option><option selected>medium</option><option>high</option></select></label><label>Owner<input id="i_owner"></label><label>Due date<input id="i_due" type="date"></label><label class="wide">Notes<textarea id="i_notes"></textarea></label><div class="actions wide"><button class="btn primary">Add</button></div></form>`)}
async function saveIssue(e){e.preventDefault();await run(async()=>{await api('issues','POST',{project_id:projectId,title:val('i_title'),kind:val('i_kind'),severity:val('i_severity'),owner_name:val('i_owner'),due_date:val('i_due'),notes:val('i_notes')});closeModal();await refresh()})}
async function setIssue(id,status){await run(async()=>{await api('issues/'+id,'PATCH',{status});await refresh()})} async function deleteIssue(id){if(!confirm('Delete this risk/issue?'))return;await run(async()=>{await api('issues/'+id,'DELETE');await refresh()})}

const taskModalV4=taskModal;taskModal=function(id,presetProject){let t=T(id)||{project_id:presetProject||projectId||'',priority:'medium',status:'todo',recurring:''},phases=(S.phases||[]).filter(x=>x.project_id===t.project_id);editingTask=id||null;let ps=S.projects.filter(p=>p.status==='active'||p.id===t.project_id).map(p=>`<option value="${p.id}" ${t.project_id===p.id?'selected':''}>${esc(p.name)}</option>`).join(''),deps=S.tasks.filter(x=>x.id!==id).map(x=>`<option value="${x.id}" ${t.depends_on===x.id?'selected':''}>${esc(x.name)}</option>`).join('');modal(id?'Edit task':'New task',`<form class="form" onsubmit="saveTaskV5(event,'${id||''}')"><label class="wide">Task name<input id="t_name" required value="${esc(t.name||'')}"></label><label>Project<select id="t_project"><option value="">Personal / no project</option>${ps}</select></label><label>Phase<select id="t_phase"><option value="">No phase</option>${phases.map(x=>`<option value="${x.id}" ${t.phase_id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label>Priority<select id="t_priority">${['low','medium','high'].map(x=>`<option ${t.priority===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Status<select id="t_status">${['todo','doing','done'].map(x=>`<option value="${x}" ${t.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Start date<input type="date" id="t_start" value="${esc(t.start_date||t.due_date||today())}"></label><label>Due date<input type="date" id="t_due" value="${esc(t.due_date||today())}"></label><label>Estimated hours<input type="number" step=".25" min="0" id="t_esth" value="${t.estimated_hours||0}"></label><label>Actual hours<input type="number" step=".25" min="0" id="t_acth" value="${t.actual_hours||0}"></label><label>Assignee<input id="t_assignee" value="${esc(t.assignee||'')}"></label><label>Tags<input id="t_tags" value="${esc(t.tags||'')}" placeholder="design, vendor, urgent"></label><label>Repeat<select id="t_recurring">${['','daily','weekdays','weekly'].map(x=>`<option value="${x}" ${t.recurring===x?'selected':''}>${x||'None'}</option>`).join('')}</select></label><label>Depends on<select id="t_dep"><option value="">No dependency</option>${deps}</select></label><label class="wide">Notes<textarea id="t_notes">${esc(t.notes||'')}</textarea></label><div class="actions wide">${id?btn('Delete task',`deleteTask('${id}')`,'danger'):''}<button class="btn primary">Save task</button></div></form>${id?`<hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><h3>Checklist</h3><div>${checklistFor(id)}</div><div class="toolbar"><input id="newCheck" placeholder="New checklist item"><button class="btn" onclick="addCheck('${id}')">Add</button></div><h3>Attachments</h3><input type="file" onchange="uploadFile(this.files[0],null,'${id}')">${filesFor(null,id)}`:''}`)}
async function saveTaskV5(e,id){e.preventDefault();await run(async()=>{let d={name:val('t_name'),project_id:val('t_project')||null,phase_id:val('t_phase')||null,start_date:val('t_start'),due_date:val('t_due'),priority:val('t_priority'),status:val('t_status'),recurring:val('t_recurring'),depends_on:val('t_dep')||null,notes:val('t_notes'),estimated_hours:val('t_esth'),actual_hours:val('t_acth'),assignee:val('t_assignee'),tags:val('t_tags')};await api(id?'tasks/'+id:'tasks',id?'PATCH':'POST',d);closeModal();await refresh()})}

function reportsView(){$('main').innerHTML=title('Reporting','Project status reports','Generate a management-ready status report for any project.')+`<div class="panel"><h2>Select a project</h2>${S.projects.map(p=>`<div class="listrow"><div><strong>${esc(p.name)}</strong><div class="small muted">${projectFacts(p.id).pct}% complete · ${esc(p.status)}</div></div>${btn('Generate report',`generateReport('${p.id}')`,'primary')}</div>`).join('')||'<div class="empty">No projects.</div>'}</div>`}
function generateReport(id){let p=P(id),f=projectFacts(id),ph=(S.phases||[]).filter(x=>x.project_id===id).sort((a,b)=>a.sort_order-b.sort_order),issues=(S.issues||[]).filter(x=>x.project_id===id&&x.status==='open'),upcoming=f.open.filter(t=>t.due_date&&t.due_date>=today()).sort((a,b)=>a.due_date.localeCompare(b.due_date)).slice(0,10),completed=f.ts.filter(t=>t.status==='done').sort((a,b)=>(b.due_date||'').localeCompare(a.due_date||'')).slice(0,10),variance=Number(p.estimated_cost||0)-f.committed,generated=new Date().toLocaleString();let w=window.open('','_blank');let rows=x=>x||'<tr><td colspan="3" class="empty">None</td></tr>';w.document.write(`<!doctype html><html><head><title>${esc(p.name)} - Project Status Report</title><style>@page{size:letter;margin:.55in}*{box-sizing:border-box}body{font:12px Segoe UI,Arial;color:#1e293b;margin:0}.head{border-bottom:4px solid #1f6f8b;padding-bottom:18px;margin-bottom:20px;display:flex;justify-content:space-between}.brand{font-weight:800;letter-spacing:.12em;color:#1f6f8b}.title{font-size:27px;font-weight:800;margin:5px 0}.meta{color:#64748b}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:15px 0}.k{border:1px solid #d9e2ec;border-radius:8px;padding:10px}.k b{font-size:18px;display:block;color:#17324d}.section{margin:20px 0;break-inside:avoid}.section h2{font-size:14px;text-transform:uppercase;letter-spacing:.08em;border-bottom:1px solid #cbd5e1;padding-bottom:6px;color:#17324d}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:7px;border-bottom:1px solid #e2e8f0;vertical-align:top}th{color:#64748b;font-size:10px;text-transform:uppercase}.bar{height:9px;background:#e2e8f0;border-radius:20px;overflow:hidden}.bar i{display:block;height:100%;background:#1f6f8b}.risk{font-weight:700}.high{color:#b42318}.foot{margin-top:30px;border-top:1px solid #cbd5e1;padding-top:10px;color:#64748b;font-size:10px}.screen{position:fixed;right:20px;top:20px}@media print{.screen{display:none}}</style></head><body><button class="screen" onclick="window.print()">Print / Save PDF</button><div class="head"><div><div class="brand">PROJECT COMMAND</div><div class="title">Project Status Report</div><div class="meta">${esc(p.name)}</div></div><div class="meta" style="text-align:right">Generated<br>${esc(generated)}<br><br>Status: <b>${esc(p.status.toUpperCase())}</b></div></div><div class="grid"><div class="k"><b>${f.pct}%</b>Task completion</div><div class="k"><b>${f.over.length}</b>Overdue tasks</div><div class="k"><b>${f.blockedN.length}</b>Pending dependencies</div><div class="k"><b>${f.days===null?'—':f.days}</b>Days to target</div></div><div class="bar"><i style="width:${f.pct}%"></i></div><div class="section"><h2>Executive summary</h2><p>${esc(p.description||'No project summary has been entered.')}</p><table><tr><th>Start</th><th>Target</th><th>Budget</th><th>Committed / Spent</th><th>Variance</th></tr><tr><td>${esc(p.start_date||'—')}</td><td>${esc(p.end_date||'—')}</td><td>${fmt(p.estimated_cost)}</td><td>${fmt(f.committed)} / ${fmt(f.spent)}</td><td>${fmt(variance)}</td></tr></table></div><div class="section"><h2>Phase status</h2><table><tr><th>Phase</th><th>Dates</th><th>Completion</th></tr>${rows(ph.map(x=>{let a=f.ts.filter(t=>t.phase_id===x.id),pc=a.length?Math.round(a.filter(t=>t.status==='done').length/a.length*100):0;return `<tr><td>${esc(x.title)}</td><td>${esc(x.start_date||'—')} → ${esc(x.end_date||'—')}</td><td>${pc}% (${a.filter(t=>t.status==='done').length}/${a.length})</td></tr>`}).join(''))}</table></div><div class="section"><h2>Milestones</h2><table><tr><th>Milestone</th><th>Target</th><th>Status</th></tr>${rows(f.ms.map(m=>`<tr><td>${esc(m.title)}</td><td>${esc(m.due_date||'—')}</td><td>${m.done?'Complete':'Open'}</td></tr>`).join(''))}</table></div><div class="section"><h2>Open risks & issues</h2><table><tr><th>Item</th><th>Type / Severity</th><th>Owner / Due</th></tr>${rows(issues.map(x=>`<tr><td class="risk ${x.severity==='high'?'high':''}">${esc(x.title)}</td><td>${esc(x.kind)} / ${esc(x.severity)}</td><td>${esc(x.owner_name||'—')} / ${esc(x.due_date||'—')}</td></tr>`).join(''))}</table></div><div class="section"><h2>Overdue / pending dependency work</h2><table><tr><th>Task</th><th>Due</th><th>Condition</th></tr>${rows([...new Map([...f.over,...f.blockedN].map(t=>[t.id,t])).values()].map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.due_date||'—')}</td><td>${f.over.includes(t)?'Overdue ':''}${f.blockedN.includes(t)?'Pending Dependency':''}</td></tr>`).join(''))}</table></div><div class="section"><h2>Upcoming work</h2><table><tr><th>Task</th><th>Due</th><th>Assignee</th></tr>${rows(upcoming.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.due_date)}</td><td>${esc(t.assignee||'—')}</td></tr>`).join(''))}</table></div><div class="section"><h2>Recently completed</h2><table><tr><th>Task</th><th>Planned finish</th><th>Hours</th></tr>${rows(completed.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.due_date||'—')}</td><td>${Number(t.actual_hours||0).toFixed(1)}</td></tr>`).join(''))}</table></div><div class="section"><h2>Project notes</h2><p>${esc(p.notes||'No notes entered.').replace(/\n/g,'<br>')}</p></div><div class="foot">JWorks 8.0 · Project Status Report · ${esc(p.name)}</div></body></html>`);w.document.close()}

const renderV4=render;render=function(){navActive();if(page==='reports')return reportsView();return renderV4()}


// ===== JWorks 8.0 =====
function daysBetween(a,b){if(!a||!b)return null;return Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000)}
function dateVariance(base,current){let n=daysBetween(base,current);return n===null?'—':`${n>0?'+':''}${n} days`}
function portfolioFacts(p){let f=projectFacts(p.id), costs=S.costs.filter(c=>c.project_id===p.id),spend=costs.reduce((a,c)=>a+Number(c.amount||0),0);return {...f,spend,variance:Number(p.estimated_cost||0)-spend}}
function dashGo(kind){if(kind==='projects'){page='projects';render();return}if(kind==='approvals'){page='approvals';render();return}page='today';render()}
function dashCollapse(id){let k='jworks-dash-'+id,v=localStorage.getItem(k)==='1';localStorage.setItem(k,v?'0':'1');render()}
function dashSection(id,titleText,body){let closed=localStorage.getItem('jworks-dash-'+id)==='1';return `<section class="dash-section ${closed?'collapsed':''}"><div class="dash-section-head" onclick="dashCollapse('${id}')"><h2>${esc(titleText)}</h2><span>${closed?'＋':'−'}</span></div>${closed?'':`<div class="dash-section-body">${body}</div>`}</section>`}
const JWORKS_FOCUS=[
 'Make the next move obvious.',
 'Small progress compounds.',
 'Build it once. Improve it often.',
 'Clarity before complexity.',
 'Finish what matters.',
 'Good systems make hard work easier.',
 'Turn the plan into motion.',
 'Keep moving the important work forward.'
];
let jwFocusIndex=Math.floor(new Date().getDate()%JWORKS_FOCUS.length),jwClockTimer=null;
function nextJWorksFocus(){jwFocusIndex=(jwFocusIndex+1)%JWORKS_FOCUS.length;let e=document.getElementById('jwFocusText');if(e)e.textContent=JWORKS_FOCUS[jwFocusIndex]}
function startJWorksClock(){
 if(jwClockTimer)clearInterval(jwClockTimer);
 const tick=()=>{let c=document.getElementById('jwClock');if(!c){clearInterval(jwClockTimer);jwClockTimer=null;return}let d=new Date(),sec=document.getElementById('jwClockSec'),dt=document.getElementById('jwDate'),f=document.getElementById('jwFocusText');c.textContent=d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});if(sec)sec.textContent=d.toLocaleTimeString([],{second:'2-digit'});if(dt)dt.textContent=d.toLocaleDateString([],{weekday:'long',month:'long',day:'numeric',year:'numeric'});if(f&&!f.dataset.set){f.textContent=JWORKS_FOCUS[jwFocusIndex];f.dataset.set='1'}};
 tick();jwClockTimer=setInterval(tick,1000);
}
function commandCenter(){
 let now=today(),active=S.projects.filter(p=>p.status==='active'),open=S.tasks.filter(t=>t.status!=='done'),over=open.filter(t=>t.due_date&&t.due_date<now),blk=open.filter(blocked),pending=(S.approvals||[]).filter(a=>a.status==='pending'),risks=(S.issues||[]).filter(x=>x.kind==='risk'&&x.status!=='closed');
 let d14=iso(new Date(new Date(now+'T12:00:00').getTime()+14*86400000)),dueWeek=open.filter(t=>t.due_date&&t.due_date>=now&&t.due_date<=iso(new Date(new Date(now+'T12:00:00').getTime()+7*86400000)));
 let attention=[...over.map(t=>({level:'OVERDUE',name:t.name,sub:`${P(t.project_id)?.name||'Personal'} · due ${t.due_date}`,pid:t.project_id})),...blk.map(t=>({level:'BLOCKED',name:t.name,sub:`${P(t.project_id)?.name||'Personal'} · dependency incomplete`,pid:t.project_id})),...pending.map(a=>({level:'APPROVAL',name:a.title,sub:P(a.project_id)?.name||'',pid:a.project_id}))].slice(0,7);
 let upcoming=[...(S.milestones||[]).filter(m=>!m.done&&m.due_date&&m.due_date>=now&&m.due_date<=d14).map(m=>({date:m.due_date,name:m.title,sub:P(m.project_id)?.name||'',pid:m.project_id,type:'Milestone'})),...open.filter(t=>t.due_date&&t.due_date>=now&&t.due_date<=d14&&(t.priority==='high'||t.due_date===now)).map(t=>({date:t.due_date,name:t.name,sub:P(t.project_id)?.name||'Personal',pid:t.project_id,type:'Task'})),...(S.procurement||[]).filter(x=>x.delivery_date&&x.delivery_date>=now&&x.delivery_date<=d14&&x.status!=='closed').map(x=>({date:x.delivery_date,name:x.item,sub:P(x.project_id)?.name||'',pid:x.project_id,type:'Delivery'}))].sort((a,b)=>a.date.localeCompare(b.date)).slice(0,8);
 let projects=active.map(p=>({p,f:projectFacts(p.id),score:projectFacts(p.id).over.length*4+projectFacts(p.id).blockedN.length*3+(projectFacts(p.id).days!==null&&projectFacts(p.id).days<=14?2:0)})).sort((a,b)=>b.score-a.score).slice(0,4);
 let my=open.filter(t=>t.due_date&&t.due_date<=iso(new Date(new Date(now+'T12:00:00').getTime()+7*86400000))).sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')).slice(0,5);
 let greet=new Date().getHours()<12?'Good morning':new Date().getHours()<17?'Good afternoon':'Good evening';
 let metrics=[['Active projects',active.length,'projects'],['Due this week',dueWeek.length,'work'],['Overdue',over.length,'work'],['Open risks',risks.length,'projects'],['Pending approvals',pending.length,'approvals']];
 let attBody=attention.map(a=>`<div class="dash-attention click" onclick="${a.pid?`openDetail('${a.pid}')`:`dashGo('work')`}"><span class="dash-level">${esc(a.level)}</span><div><b>${esc(a.name)}</b><div class="small muted">${esc(a.sub)}</div></div><span class="dash-arrow">›</span></div>`).join('')||'<div class="dash-clear">Nothing urgent is demanding attention right now.</div>';
 let projectBody=`<div class="dash-project-grid">${projects.map(({p,f})=>`<div class="dash-project click" onclick="openDetail('${p.id}')"><div class="small muted">${esc(p.project_code||'PROJECT')}</div><h3>${esc(p.name)}</h3><div class="dash-progress"><i style="width:${f.pct}%"></i></div><div class="between small"><span>${f.pct}% complete</span><span>${p.end_date?esc(p.end_date):'No target'}</span></div><div class="dash-project-facts"><span>${f.open.length} open</span><span>${f.over.length} overdue</span><span>${f.blockedN.length} pending dependenc${f.blockedN.length===1?'y':'ies'}</span></div></div>`).join('')}</div>${active.length>4?`<button class="btn" onclick="dashGo('projects')">View all ${active.length} projects</button>`:''}`;
 let upBody=upcoming.map(x=>`<div class="dash-timeline click" onclick="${x.pid?`openDetail('${x.pid}')`:''}"><div class="dash-date">${x.date===now?'TODAY':new Date(x.date+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'})}</div><div><b>${esc(x.name)}</b><div class="small muted">${esc(x.type)} · ${esc(x.sub)}</div></div></div>`).join('')||'<div class="dash-clear">No high-priority tasks, milestones or deliveries in the next 14 days.</div>';
 let workBody=`<div class="dash-work-counts"><span><b>${open.filter(t=>t.due_date===now).length}</b> Today</span><span><b>${dueWeek.length}</b> This week</span><span><b>${over.length}</b> Overdue</span><span><b>${open.filter(t=>t.priority==='high').length}</b> High priority</span></div>${my.map(t=>`<div class="listrow click" onclick="taskDrawer('${t.id}')"><div>□ ${esc(t.name)}<div class="small muted">${esc(P(t.project_id)?.name||'Personal')} · ${esc(t.due_date||'')}</div></div></div>`).join('')||'<div class="dash-clear">No dated work due this week.</div>'}<button class="btn" onclick="dashGo('work')">View My Work</button>`;
 $('main').innerHTML=`<div class="dash-hero"><div><div class="eyebrow">JWORKS · COMMAND CENTER</div><h1>${greet}.</h1><p>${active.length} active project${active.length===1?'':'s'} · ${attention.length?attention.length+' priority item'+(attention.length===1?'':'s')+' need attention':'No urgent items'} · ${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</p></div><div class="actions">${btn('+ Task','taskModal()')}${btn('+ Project','projectModal()','primary')}</div></div>
 <div class="dash-kpis">${metrics.map(([k,v,g])=>`<button class="dash-kpi" onclick="dashGo('${g}')"><strong>${v}</strong><span>${k}</span></button>`).join('')}</div>
 <div class="dash-ai"><div><div class="eyebrow">✦ JWORKS AI</div><b>Want a project briefing?</b><div class="small muted">Summarize your projects, overdue work, milestones, risks and approvals.</div></div><div class="actions"><button class="btn primary" onclick="page='assistant';render()">Brief me</button><button class="btn" onclick="page='assistant';render()">Ask JWorks</button></div></div>
 <div class="focus-deck">
   <div class="focus-clock"><span id="jwClock">--:--</span><small id="jwClockSec">--</small><div id="jwDate"></div></div>
   <div class="focus-divider"></div>
   <div class="focus-message"><div class="eyebrow">TODAY'S FOCUS</div><div id="jwFocusText">Make the next move obvious.</div><button class="focus-next" onclick="nextJWorksFocus()">↻ New focus</button></div>
   <div class="focus-mark">JW</div>
 </div>
 ${dashSection('attention','Needs Your Attention',attBody)}
 <div class="dash-two">${dashSection('projects','Active Projects',projectBody)}${dashSection('upcoming','Next 14 Days',upBody)}</div>
 ${dashSection('work','My Work',workBody)}`;
 setTimeout(startJWorksClock,0);
}
function portfolioView(){let ps=S.projects.filter(p=>p.status==='active');$('main').innerHTML=title('Cross-project analytics','Portfolio','Compare schedule, workload and financial facts across active projects.',`<a class="btn" href="/api/portfolio.csv">Export CSV</a>`)+`<div class="panel" style="overflow:auto"><table class="portfolio-table"><thead><tr><th>Project</th><th>Complete</th><th>Target</th><th>Overdue</th><th>Pending Dependency</th><th>Budget</th><th>Committed/Spent</th><th>Variance</th></tr></thead><tbody>${ps.map(p=>{let f=portfolioFacts(p);return `<tr class="click" onclick="openDetail('${p.id}')"><td><strong>${esc(p.name)}</strong></td><td>${f.pct}%</td><td>${esc(p.end_date||'—')}</td><td>${f.over.length}</td><td>${f.blockedN.length}</td><td>${fmt(p.estimated_cost)}</td><td>${fmt(f.spend)}</td><td>${fmt(f.variance)}</td></tr>`}).join('')}</tbody></table></div>`}
function inboxView(){$('main').innerHTML=title('Capture first, organize later','Inbox','Quickly capture work without choosing a project or date.',btn('+ Capture','inboxModal()','primary'))+`<div class="panel">${S.inbox.map(x=>`<div class="listrow"><div><strong>${esc(x.title)}</strong><div class="small muted">${esc(x.notes||'')} · ${new Date(x.created_at).toLocaleString()}</div></div><div>${btn('Make task',`inboxToTask('${x.id}')`)}${btn('Delete',`deleteInbox('${x.id}')`,'danger')}</div></div>`).join('')||'<div class="empty">Inbox is clear.</div>'}</div>`}
function searchView(){let q=window.v8q||'';$('main').innerHTML=title('Everything in one place','Global Search','Search projects, tasks, risks, meetings, changes and activity.')+`<input class="searchbox" placeholder="Search JWorks..." value="${esc(q)}" oninput="window.v8q=this.value;searchView()"><div class="panel" style="margin-top:14px">${globalResults(q)}</div>`}
function globalResults(q){q=(q||'').trim().toLowerCase();if(!q)return '<div class="empty">Start typing to search.</div>';let out=[];S.projects.filter(x=>(x.name+' '+x.description).toLowerCase().includes(q)).forEach(x=>out.push(`<div class="listrow click" onclick="openDetail('${x.id}')"><div><b>Project · ${esc(x.name)}</b><div class="small muted">${esc(x.description)}</div></div></div>`));S.tasks.filter(x=>(x.name+' '+x.notes+' '+x.tags).toLowerCase().includes(q)).forEach(x=>out.push(`<div class="listrow click" onclick="taskModal('${x.id}')"><div><b>Task · ${esc(x.name)}</b><div class="small muted">${esc(P(x.project_id)?.name||'Personal')}</div></div></div>`));S.issues.filter(x=>(x.title+' '+x.notes).toLowerCase().includes(q)).forEach(x=>out.push(`<div class="listrow"><div><b>${esc(x.kind)} · ${esc(x.title)}</b><div class="small muted">${esc(P(x.project_id)?.name||'')}</div></div></div>`));S.meetings.filter(x=>(x.title+' '+x.notes+' '+x.decisions).toLowerCase().includes(q)).forEach(x=>out.push(`<div class="listrow"><div><b>Meeting · ${esc(x.title)}</b><div class="small muted">${esc(P(x.project_id)?.name||'')}</div></div></div>`));return out.slice(0,60).join('')||'<div class="empty">No matches.</div>'}
function notificationsView(){let overdue=S.tasks.filter(t=>t.status!=='done'&&t.due_date&&t.due_date<today());$('main').innerHTML=title('Attention feed','Notifications','System-generated attention items and saved notifications.')+`<div class="panel"><h2>Current alerts</h2>${overdue.map(t=>`<div class="alertrow click" onclick="taskDrawer('${t.id}')">Overdue · ${esc(t.name)} · ${esc(t.due_date)}</div>`).join('')||'<div class="empty">No current alerts.</div>'}${S.notifications.map(n=>`<div class="listrow"><div>${esc(n.message)}<div class="small muted">${new Date(n.created_at).toLocaleString()}</div></div>${!n.is_read?btn('Mark read',`markNotification('${n.id}')`):'<span class="pill">Read</span>'}</div>`).join('')}</div>`}
function inboxModal(){modal('Capture to Inbox',`<div class="form"><label class="wide">Item<input id="ibTitle" autofocus></label><label class="wide">Notes<textarea id="ibNotes"></textarea></label></div><div class="actions">${btn('Cancel','closeModal()')}${btn('Capture','saveInbox()','primary')}</div>`)}
async function saveInbox(){await run(async()=>{await api('inbox','POST',{title:val('ibTitle'),notes:val('ibNotes')});closeModal();await refresh();page='inbox';render()})}
async function deleteInbox(id){await run(async()=>{await api('inbox/'+id,'DELETE');await refresh()})}
function inboxToTask(id){let x=S.inbox.find(a=>a.id===id);if(!x)return;taskModal();setTimeout(()=>{if($('tname'))$('tname').value=x.title;if($('tnotes'))$('tnotes').value=x.notes||''},0)}
async function markNotification(id){await run(async()=>{await api('notifications/'+id,'PATCH',{});await refresh()})}
async function captureBaseline(pid){if(!confirm('Capture the current target date, budget and task schedule as a new baseline?'))return;await run(async()=>{await api('baselines','POST',{project_id:pid});await refresh();toast('Baseline captured')})}
function meetingModal(){modal('Record meeting',`<div class="form"><label class="wide">Title<input id="mtitle"></label><label>Date<input id="mdate" type="date" value="${today()}"></label><label>Attendees<input id="matt"></label><label class="wide">Notes<textarea id="mnotes"></textarea></label><label class="wide">Decisions<textarea id="mdec"></textarea></label></div><div class="actions">${btn('Cancel','closeModal()')}${btn('Save meeting','saveMeeting()','primary')}</div>`)}
async function saveMeeting(){await run(async()=>{await api('meetings','POST',{project_id:projectId,title:val('mtitle'),meeting_date:val('mdate'),attendees:val('matt'),notes:val('mnotes'),decisions:val('mdec')});closeModal();await refresh()})}
function changeModal(){modal('Record project change',`<div class="form"><label class="wide">Change title<input id="ctitle"></label><label>Cost impact<input id="ccost" type="number" step="0.01"></label><label>Schedule impact (days)<input id="cdays" type="number" value="0"></label><label>Status<select id="cstatus"><option>proposed</option><option>approved</option><option>rejected</option></select></label><label class="wide">Description<textarea id="cdesc"></textarea></label></div><div class="actions">${btn('Cancel','closeModal()')}${btn('Save change','saveChange()','primary')}</div>`)}
async function saveChange(){await run(async()=>{await api('changes','POST',{project_id:projectId,title:val('ctitle'),description:val('cdesc'),cost_impact:val('ccost'),schedule_days:val('cdays'),status:val('cstatus')});closeModal();await refresh()})}
async function setChange(id,status){await run(async()=>{await api('changes/'+id,'PATCH',{status});await refresh()})}
async function saveReportSnapshot(pid){let title=prompt('Snapshot title','Status Report '+today());if(!title)return;await run(async()=>{await api('report-snapshots','POST',{project_id:pid,title});await refresh();toast('Report snapshot saved')})}
function whatIf(pid){let p=P(pid),days=Number(prompt('Temporarily shift the project schedule by how many days?','14'));if(!Number.isFinite(days))return;let affected=S.tasks.filter(t=>t.project_id===pid&&t.status!=='done'&&t.due_date).length,newTarget=p.end_date?iso(new Date(new Date(p.end_date+'T12:00:00').getTime()+days*86400000)):'No target';alert(`WHAT-IF SCENARIO\n\nCurrent target: ${p.end_date||'No target'}\nScenario target: ${newTarget}\nSchedule impact: ${days>=0?'+':''}${days} days\nOpen dated tasks affected: ${affected}\n\nThis scenario did not change your project.`)}
const renderPreV8=render;render=function(){navActive();if(page==='dashboard')return commandCenter();if(page==='portfolio')return portfolioView();if(page==='inbox')return inboxView();if(page==='search')return searchView();if(page==='notifications')return notificationsView();return renderPreV8()}
const projectDetailPreV8=projectDetail;projectDetail=function(){projectDetailPreV8();let p=P(projectId);if(!p)return;let top=document.querySelector('#main .top .actions');if(top){top.insertAdjacentHTML('beforeend',btn('What-if',`whatIf('${p.id}')`)+btn('Save report snapshot',`saveReportSnapshot('${p.id}')`))}}

// V8 project workspace extension (loaded after V5 workspace renderer)
projectDetail=function(){
  projectDetailPreV8(); let p=P(projectId); if(!p)return;
  let tabsEl=document.querySelector('#main .tabs');
  if(tabsEl){['meetings','changes','intelligence'].forEach(t=>tabsEl.insertAdjacentHTML('beforeend',`<button class="${tab===t?'active':''}" onclick="tab='${t}';render()">${t[0].toUpperCase()+t.slice(1)}</button>`));}
  let top=document.querySelector('#main .top .actions');
  if(top)top.insertAdjacentHTML('beforeend',btn('What-if',`whatIf('${p.id}')`)+btn('Save report snapshot',`saveReportSnapshot('${p.id}')`));
  let pane=$('projectPane'); if(!pane)return;
  if(tab==='meetings')pane.innerHTML=`<div class="panel"><div class="between"><h2>Meetings & decisions</h2>${btn('+ Meeting','meetingModal()','primary')}</div>${S.meetings.filter(x=>x.project_id===p.id).map(x=>`<div class="phase"><strong>${esc(x.title)}</strong><div class="small muted">${esc(x.meeting_date||'')} · ${esc(x.attendees||'No attendees listed')}</div><p>${esc(x.notes||'').replace(/\n/g,'<br>')}</p>${x.decisions?`<div class="small"><b>Decisions:</b> ${esc(x.decisions)}</div>`:''}</div>`).join('')||'<div class="empty">No meetings recorded.</div>'}</div>`;
  else if(tab==='changes')pane.innerHTML=`<div class="panel"><div class="between"><h2>Change log</h2>${btn('+ Change','changeModal()','primary')}</div>${S.changes.filter(x=>x.project_id===p.id).map(x=>`<div class="listrow"><div><strong>${esc(x.title)}</strong><div class="small muted">${esc(x.status)} · Cost ${fmt(x.cost_impact)} · Schedule ${Number(x.schedule_days)>=0?'+':''}${x.schedule_days} days</div></div><div>${x.status==='proposed'?btn('Approve',`setChange('${x.id}','approved')`)+btn('Reject',`setChange('${x.id}','rejected')`):''}</div></div>`).join('')||'<div class="empty">No changes recorded.</div>'}</div>`;
  else if(tab==='intelligence'){let b=S.baselines.filter(x=>x.project_id===p.id).sort((a,b)=>b.created_at.localeCompare(a.created_at))[0],f=projectFacts(p.id);pane.innerHTML=`<div class="grid"><div class="panel"><div class="between"><h2>Approved baseline</h2>${btn(b?'Capture new baseline':'Set baseline',`captureBaseline('${p.id}')`,'primary')}</div>${b?`<div class="baseline phase">Captured ${new Date(b.created_at).toLocaleString()}<br>Baseline target: <b>${esc(b.target_date||'—')}</b><br>Baseline budget: <b>${fmt(b.budget)}</b><br>Current target variance: <b>${dateVariance(b.target_date,p.end_date)}</b><br>Budget-plan variance: <b>${fmt(Number(p.estimated_cost||0)-Number(b.budget||0))}</b></div>`:'<div class="empty">Capture an approved schedule and budget baseline.</div>'}</div><div class="panel"><h2>Current evidence</h2><div class="listrow"><span>Completion</span><b>${f.pct}%</b></div><div class="listrow"><span>Overdue</span><b>${f.over.length}</b></div><div class="listrow"><span>Pending Dependency</span><b>${f.blockedN.length}</b></div><div class="listrow"><span>Open risks/issues</span><b>${S.issues.filter(i=>i.project_id===p.id&&i.status==='open').length}</b></div><div class="listrow"><span>Approved changes</span><b>${S.changes.filter(i=>i.project_id===p.id&&i.status==='approved').length}</b></div></div></div>`;}
}


// ===== JWorks 9.0 =====
const renderV8=render;
render=function(){
 navActive();
 if(page==='saved')return savedViewsPage();
 if(page==='automations')return automationsPage();
 if(page==='admin')return adminPage();
 return renderV8();
}
function closeDrawer(){$('drawerRoot').innerHTML=''}
function taskDrawer(id){
 let t=T(id);if(!t)return;let p=P(t.project_id),checks=S.checklist.filter(x=>x.task_id===id);
 $('drawerRoot').innerHTML=`<div class="drawerback" onclick="closeDrawer()"></div><aside class="drawer"><div class="between"><div><div class="eyebrow">${esc(p?.name||'Personal task')}</div><h2>${esc(t.name)}</h2></div><button class="btn" onclick="closeDrawer()">✕</button></div><div class="form"><label>Status<select id="dstatus"><option value="todo">To do</option><option value="doing">In progress</option><option value="done">Done</option></select></label><label>Priority<select id="dpriority"><option>low</option><option>medium</option><option>high</option></select></label><label>Start<input id="dstart" type="date" value="${esc(t.start_date||'')}"></label><label>Finish<input id="ddue" type="date" value="${esc(t.due_date||'')}"></label><label>Progress %<input id="dprogress" type="number" min="0" max="100" value="${Number(t.progress||0)}"></label><label>Assignee<input id="dassignee" value="${esc(t.assignee||'')}"></label><label class="wide">Notes<textarea id="dnotes">${esc(t.notes||'')}</textarea></label></div><h3>Checklist</h3>${checks.map(c=>`<div class="checkrow"><input type="checkbox" ${c.done?'checked':''} onchange="toggleCheck('${c.id}',this.checked)"><span>${esc(c.title)}</span></div>`).join('')||'<div class="small muted">No checklist items.</div>'}<div class="actions" style="margin-top:18px"><button class="btn" onclick="closeDrawer();taskModal('${id}')">Full editor</button><button class="btn primary" onclick="saveDrawer('${id}')">Save</button></div></aside>`;
 $('dstatus').value=t.status;$('dpriority').value=t.priority;
}
async function saveDrawer(id){let t=T(id);await run(async()=>{await api('tasks/'+id,'PATCH',{...t,status:val('dstatus'),priority:val('dpriority'),start_date:val('dstart'),due_date:val('ddue'),progress:Number(val('dprogress')||0),assignee:val('dassignee'),notes:val('dnotes')});closeDrawer();await refresh();toast('Task updated')})}
function savedViewsPage(){
 let presets=[['My overdue tasks',{kind:'overdue'}],['High priority open',{kind:'high'}],['Projects closing this month',{kind:'closing'}],['Open risks',{kind:'risks'}]];
 $('main').innerHTML=title('Reusable filters','Saved Views','Keep common views one click away.')+`<div class="panel"><h2>Quick views</h2>${presets.map(([n,f])=>`<span class="savedchip click" onclick='showSaved(${JSON.stringify(JSON.stringify(f))},"${esc(n)}")'>☆ ${esc(n)}</span>`).join('')}<h2 style="margin-top:22px">Your saved views</h2>${S.saved_views.map(v=>`<div class="listrow"><div class="click" onclick='showSaved(${JSON.stringify(v.filter_json)},"${esc(v.title)}")'><b>${esc(v.title)}</b></div>${btn('Delete',`deleteSaved('${v.id}')`,'danger')}</div>`).join('')||'<div class="empty">No custom views yet.</div>'}<div style="margin-top:15px">${btn('+ Save a view','savedViewModal()','primary')}</div></div><div id="savedResults"></div>`;
}
function savedViewModal(){modal('Save View',`<div class="form"><label class="wide">Name<input id="svname"></label><label>Filter<select id="svkind"><option value="overdue">Overdue tasks</option><option value="high">High priority open tasks</option><option value="closing">Projects closing this month</option><option value="risks">Open risks</option></select></label></div><div class="actions">${btn('Cancel','closeModal()')}${btn('Save','saveView()','primary')}</div>`)}
async function saveView(){await run(async()=>{await api('saved-views','POST',{title:val('svname'),filter:{kind:val('svkind')}});closeModal();await refresh();page='saved';render()})}
async function deleteSaved(id){await run(async()=>{await api('saved-views/'+id,'DELETE');await refresh()})}
function showSaved(raw,name){let f=typeof raw==='string'?JSON.parse(raw):raw,k=f.kind,h='';if(k==='overdue')h=S.tasks.filter(t=>t.status!=='done'&&t.due_date&&t.due_date<today()).map(taskRow).join('');if(k==='high')h=S.tasks.filter(t=>t.status!=='done'&&t.priority==='high').map(taskRow).join('');if(k==='closing'){let now=new Date(),m=now.getMonth(),y=now.getFullYear();h=S.projects.filter(p=>p.end_date&&new Date(p.end_date+'T12:00:00').getMonth()===m&&new Date(p.end_date+'T12:00:00').getFullYear()===y).map(p=>`<div class="listrow click" onclick="openDetail('${p.id}')"><b>${esc(p.name)}</b><span>${esc(p.end_date)}</span></div>`).join('')}if(k==='risks')h=S.issues.filter(x=>x.status==='open').map(x=>`<div class="listrow"><b>${esc(x.title)}</b><span>${esc(P(x.project_id)?.name||'')}</span></div>`).join('');$('savedResults').innerHTML=`<div class="panel" style="margin-top:15px"><h2>${esc(name)}</h2>${h||'<div class="empty">Nothing matches this view.</div>'}</div>`}
function automationsPage(){$('main').innerHTML=title('No-code rules','Automations','Create lightweight rules for attention and workflow.',btn('+ Rule','ruleModal()','primary'))+`<div class="panel">${S.automation_rules.map(r=>`<div class="listrow"><div><b>${esc(r.title)}</b><div class="small muted">${esc(r.trigger_type)} → ${esc(r.action_type)}</div></div><div><label class="pill"><input type="checkbox" ${r.enabled?'checked':''} onchange="toggleRule('${r.id}',this.checked)"> Enabled</label> ${btn('Delete',`deleteRule('${r.id}')`,'danger')}</div></div>`).join('')||'<div class="empty">No automation rules yet.</div>'}</div>`}
function ruleModal(){modal('Automation Rule',`<div class="form"><label class="wide">Rule name<input id="rname"></label><label>When<select id="rtrigger"><option value="task_overdue">Task becomes overdue</option><option value="task_completed">Task is completed</option><option value="milestone_approaching">Milestone approaches</option></select></label><label>Then<select id="raction"><option value="notification">Create notification</option></select></label></div><div class="actions">${btn('Cancel','closeModal()')}${btn('Save rule','saveRule()','primary')}</div>`)}
async function saveRule(){await run(async()=>{await api('automation-rules','POST',{title:val('rname'),trigger_type:val('rtrigger'),action_type:val('raction')});closeModal();await refresh();page='automations';render()})}
async function toggleRule(id,on){await run(async()=>{await api('automation-rules/'+id,'PATCH',{enabled:on});await refresh()})}
async function deleteRule(id){await run(async()=>{await api('automation-rules/'+id,'DELETE');await refresh()})}
async function adminPage(){
 $('main').innerHTML=title('Reliability & storage','Administration','Cloud database health and secure AI integration.')+`<div id="sys" class="panel">Loading system status…</div><div class="panel" style="margin-top:15px"><div class="between"><div><h2>AI Project Assistant</h2><p class="muted">OpenRouter is configured securely through your Cloudflare Worker secret.</p></div>${btn('AI Settings','aiSettings()')}</div><div id="aistat">Checking…</div></div>`;
 try{let s=await api('system-status');$('sys').innerHTML=`<div class="between"><h2>System</h2><span class="pill">Cloud</span></div><div class="sysgrid"><div class="syscard"><div class="muted small">Database</div><b>${esc(s.database)}</b></div><div class="syscard"><div class="muted small">Projects</div><b>${s.projects}</b></div><div class="syscard"><div class="muted small">Tasks</div><b>${s.tasks}</b></div><div class="syscard"><div class="muted small">Documents</div><b>${s.attachments}</b></div></div><p class="small muted" style="margin-top:12px">JWorks Cloud uses Cloudflare D1. Local Windows backup controls do not apply to this deployment.</p>`}catch(e){$('sys').innerHTML=`<b>System status unavailable</b><p class="muted">${esc(e.message)}</p>`}
 try{let ai=await api('ai-status');$('aistat').innerHTML=`<div class="between"><div><span class="pill">${ai.enabled?'Configured':'Not configured'}</span> <span>${esc(ai.message)}</span><div class="small muted" style="margin-top:7px">Model: ${esc(ai.model||'openrouter/free')}</div></div>${ai.enabled?btn('Test AI Connection','testAIConnection()','primary'):''}</div>`}catch(e){$('aistat').innerHTML=`<b>AI status unavailable</b><p class="muted">${esc(e.message)}</p>`}
}
function humanBytes(n){for(let u of ['B','KB','MB','GB']){if(n<1024)return `${Number(n).toFixed(u==='B'?0:1)} ${u}`;n/=1024}return `${n.toFixed(1)} TB`}
async function backupNow(){await run(async()=>{let r=await api('backup-now','POST',{});toast('Backup created: '+r.file);adminPage()})}
async function issueReportV9(pid){let title=prompt('Report title','Project Status Report');if(!title)return;await run(async()=>{let r=await api('report-revisions','POST',{project_id:pid,title,config:{executive:true,schedule:true,financial:true,risks:true,work:true}});toast(`${title} Rev ${r.revision} saved`);await refresh()})}
function reportBuilderV9(pid){let p=P(pid);if(!p)return;modal('Report Builder',`<div class="form"><label class="wide">Report title<input id="rbtitle" value="Project Status Report"></label><label>Period start<input id="rbstart" type="date"></label><label>Period end<input id="rbend" type="date" value="${today()}"></label><label class="wide"><b>Sections</b><span class="small muted">The generated report uses your current project data.</span></label><label><span><input id="rbexec" type="checkbox" checked> Executive summary</span></label><label><span><input id="rbsched" type="checkbox" checked> Schedule & phases</span></label><label><span><input id="rbfin" type="checkbox" checked> Financials</span></label><label><span><input id="rbrisks" type="checkbox" checked> Risks & issues</span></label><label><span><input id="rbwork" type="checkbox" checked> Work status</span></label></div><div class="actions">${btn('Cancel','closeModal()')}${btn('Generate','generateV9Report()','primary')}</div>`)}
function generateV9Report(){let title=val('rbtitle')||'Project Status Report';closeModal();statusReport(projectId);setTimeout(()=>issueReportV9(projectId),250)}
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));

const projectDetailV8=projectDetail;projectDetail=function(){projectDetailV8();let p=P(projectId);if(!p)return;let top=document.querySelector('#main .top .actions');if(top)top.insertAdjacentHTML('beforeend',btn('Report Builder',`reportBuilderV9('${p.id}')`,'primary'));let pane=$('projectPane');if(tab==='reports'&&pane){pane.insertAdjacentHTML('afterbegin',`<div class="panel" style="margin-bottom:12px"><h2>V9 Report Revisions</h2>${S.report_revisions.filter(r=>r.project_id===p.id).map(r=>`<div class="listrow"><b>${esc(r.title)} · Rev ${r.revision}</b><span class="small muted">${new Date(r.created_at).toLocaleString()}</span></div>`).join('')||'<div class="small muted">No issued V9 revisions yet.</div>'}</div>`)}} 


// ===== JWorks 10.1 AI Assistant =====
const renderV9=render;render=function(){navActive();if(page==='assistant')return aiAssistantPage();return renderV9()}
function aiAssistantPage(){
 let opts=S.projects.filter(p=>p.status!=='archived').map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');
 $('main').innerHTML=title('General + project-aware AI','AI Assistant','Ask general questions, work with project context, or turn an AI plan into tasks.',btn('AI Settings','aiSettings()'))+`<div class="grid"><div class="panel"><label class="small muted">Project context (optional)</label><select id="aiProject" style="width:100%;margin:7px 0 12px"><option value="">General question — no project context</option>${opts}</select><div id="aiThread" style="min-height:260px;max-height:520px;overflow:auto"><div class="empty">Ask anything. Select a project above when you want the assistant to use that project's data.</div></div><textarea id="aiQuestion" placeholder="Example: What is the best way to plan and pour a concrete pad?" style="width:100%;margin-top:12px"></textarea><div class="actions" style="margin-top:9px">${btn('Ask AI','askAI()','primary')}${btn('Build task plan from this','buildAIPlan()')}</div></div><div class="panel"><h2>AI → Tasks</h2><p class="muted">The assistant can propose tasks, but nothing is written to your database until you approve it.</p><div id="aiPlan"><div class="empty">A generated task plan will appear here for review.</div></div></div></div>`;
 if(window.aiProjectPreset&&$('aiProject')){$('aiProject').value=window.aiProjectPreset;window.aiProjectPreset=null}
}
async function askAI(){let q=val('aiQuestion');if(!q)return;let th=$('aiThread');th.innerHTML=`<div class="phase"><b>You</b><p>${esc(q)}</p></div><div class="phase"><b>JWorks AI</b><p class="muted">Thinking…</p></div>`;await run(async()=>{let r=await api('ai-chat','POST',{message:q,project_id:val('aiProject')||null});th.lastElementChild.innerHTML=`<b>JWorks AI</b><p style="white-space:pre-wrap">${esc(r.answer)}</p>`})}
function renderAIPlan(summary=''){
 let tasks=window.aiProposed||[];
 $('aiPlan').innerHTML=`${summary?`<p>${esc(summary)}</p>`:''}<div class="small muted" style="margin-bottom:10px">Review the plan before creating anything. Edit any step, remove it, add your own, or move steps up/down.</div>
 ${tasks.map((t,i)=>`<div class="phase ai-edit-step" data-i="${i}"><div class="between"><b>Step ${i+1}</b><div>${btn('↑',`moveAIStep(${i},-1)`)}${btn('↓',`moveAIStep(${i},1)`)}${btn('Remove',`removeAIStep(${i})`,'danger')}</div></div><div class="form" style="margin-top:8px"><label class="wide">Task<input class="aiName" data-i="${i}" value="${esc(t.name||'')}"></label><label>Priority<select class="aiPriority" data-i="${i}">${['low','medium','high'].map(x=>`<option ${t.priority===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Est. hours<input class="aiHours" data-i="${i}" type="number" min="0" step=".5" value="${Number(t.estimated_hours||0)}"></label><label class="wide">Notes<textarea class="aiNotes" data-i="${i}">${esc(t.notes||'')}</textarea></label></div></div>`).join('')||'<div class="empty">No steps yet. Add one below.</div>'}
 <div class="actions">${btn('+ Add step','addAIStep()')}${tasks.length?btn('Create these tasks','approveAIPlan()','primary'):''}</div>`;
}
function syncAIPlanEdits(){(window.aiProposed||[]).forEach((t,i)=>{let n=document.querySelector(`.aiName[data-i="${i}"]`),p=document.querySelector(`.aiPriority[data-i="${i}"]`),h=document.querySelector(`.aiHours[data-i="${i}"]`),no=document.querySelector(`.aiNotes[data-i="${i}"]`);if(n)t.name=n.value;if(p)t.priority=p.value;if(h)t.estimated_hours=Number(h.value||0);if(no)t.notes=no.value})}
function removeAIStep(i){syncAIPlanEdits();window.aiProposed.splice(i,1);renderAIPlan()}
function addAIStep(){syncAIPlanEdits();window.aiProposed.push({name:'New step',notes:'',priority:'medium',estimated_hours:0});renderAIPlan();setTimeout(()=>{let a=document.querySelectorAll('.aiName');if(a.length){a[a.length-1].focus();a[a.length-1].select()}},0)}
function moveAIStep(i,d){syncAIPlanEdits();let j=i+d;if(j<0||j>=window.aiProposed.length)return;[window.aiProposed[i],window.aiProposed[j]]=[window.aiProposed[j],window.aiProposed[i]];renderAIPlan()}
async function buildAIPlan(){let q=val('aiQuestion');if(!q)return;$('aiPlan').innerHTML='<div class="empty">Building proposed tasks…</div>';await run(async()=>{let r=await api('ai-task-plan','POST',{prompt:q,project_id:val('aiProject')||null});window.aiProposed=(r.tasks||[]).map(t=>({...t}));renderAIPlan(r.summary||'')})}
async function approveAIPlan(){syncAIPlanEdits();let pid=val('aiProject')||null;if(!pid&&!confirm('No project is selected. Create these as personal tasks?'))return;let picks=(window.aiProposed||[]).filter(t=>(t.name||'').trim());if(!picks.length)return alert('Add at least one task before creating the plan.');if(!confirm(`Create ${picks.length} reviewed task${picks.length===1?'':'s'}?`))return;await run(async()=>{let r=await api('ai-create-tasks','POST',{project_id:pid,tasks:picks});toast(`${r.count} AI-planned tasks created`);window.aiProposed=[];await refresh();page=pid?'projects':'today';if(pid)projectId=pid;render()})}
async function aiSettings(){await run(async()=>{let c=await api('ai-config');modal('AI Configuration',`<div class="panel" style="margin:0"><div class="between"><div><div class="small muted">PROVIDER</div><h2 style="margin:4px 0">OpenRouter</h2></div><span class="pill">${c.configured?'Configured':'Not configured'}</span></div><p class="muted">JWorks Cloud keeps your API key in a Cloudflare Worker secret. The key is never returned to this browser or stored in GitHub/D1.</p><div class="form"><label>Model<input value="${esc(c.model||'openrouter/free')}" disabled></label><label>Secret location<input value="Cloudflare Worker secret" disabled></label></div>${c.configured?`<div class="actions">${btn('Close','closeModal()')}${btn('Test AI Connection','testAIConnection()','primary')}</div>`:`<div class="empty">Add a Cloudflare Worker secret named <b>OPENROUTER_API_KEY</b>, then redeploy JWorks.</div><div class="actions">${btn('Close','closeModal()')}</div>`}</div>` )})}
async function testAIConnection(){await run(async()=>{let res=await fetch('/api/ai-test',{method:'POST',headers:{'X-CSRF-Token':csrf,'Content-Type':'application/json'},body:'{}'});let r=await res.json();let d=r.diagnostics||{};let attempts=d.key_probe_attempts||d.auth_probe_attempts||[];let probeLines=attempts.length?['','OpenRouter auth probes:',...attempts.map(a=>`• ${a.name}: ${a.ok?'✓ PASS':'✕ FAIL'}${a.status?' (HTTP '+a.status+')':''}${a.redirected?' — redirected':''}${a.response_url?' — '+a.response_url:''}${a.error?' — '+a.error:''}`)]:[];let lines=['JWorks AI Diagnostics — V11.2.7','',`JWorks AI Worker: ${d.ai_worker_reached?'✓ Reached':'✕ Not reached'}`,`AI Worker secret detected: ${d.ai_worker_secret_present?'✓ Yes':'✕ No'}`,`AI Worker secret non-empty: ${d.ai_worker_secret_nonempty?'✓ Yes':'✕ No'}`,`OpenRouter key format: ${d.key_format_openrouter?'✓ sk-or-*':'✕ unexpected format'}`,`Key length: ${d.key_length||0} characters`,`Authorization header exists: ${d.authorization_header_present?'✓ Yes':'✕ No'}`,`Transport: ${d.transport||'unknown'}`,`Working auth method: ${d.key_probe_working_method||d.auth_probe_working_method||'none'}`,`OpenRouter key endpoint: ${d.key_endpoint_reached?'✓ Reached':'✕ Not reached'}`,`OpenRouter authentication: ${d.key_authenticated?'✓ PASS':'✕ FAIL'}${d.key_endpoint_status?' (HTTP '+d.key_endpoint_status+')':''}`,...probeLines,`Chat endpoint reached: ${d.openrouter_reached?'✓ Yes':'—'}`,`Chat authenticated: ${d.openrouter_authenticated?'✓ PASS':'✕ FAIL'}`,'',res.ok?(r.message||'Connection successful'):(r.error||d.key_error||`Server error (${res.status})`)];alert(lines.join('\n'));if(page==='admin'){closeModal();adminPage()}})}
function openProjectAI(pid){window.aiProjectPreset=pid;page='assistant';projectId=null;render()}

const projectDetailV91=projectDetail;projectDetail=function(){projectDetailV91();let p=P(projectId);if(!p)return;let top=document.querySelector('#main .top .actions');if(top)top.insertAdjacentHTML('beforeend',btn('✦ Ask AI',`openProjectAI('${p.id}')`,'primary'))}


// ===== JWorks 10.1 =====
const renderV91=render;render=function(){navActive();if(page==='roadmap')return roadmapV10();if(page==='templates')return templatesV10();if(page==='projectbuilder')return projectBuilderV10();if(page==='approvals')return approvalsV10();return renderV91()}
function projectBuilderV10(){$('main').innerHTML=title('AI → complete project','AI Project Builder','Describe the outcome. AI proposes phases, tasks, dependencies, milestones and risks; you approve before anything is created.')+`<div class="grid"><div class="panel"><h2>Describe the project</h2><textarea id="pbPrompt" style="width:100%;min-height:180px" placeholder="Example: Replace a 20 x 30 concrete equipment pad. Include planning, demolition, base preparation, reinforcement, pour, curing and closeout."></textarea><div class="form" style="margin-top:10px"><label>Start date<input id="pbStart" type="date" value="${today()}"></label><label>Target date<input id="pbEnd" type="date"></label></div><div class="actions" style="margin-top:12px">${btn('Build project proposal','buildProjectAI()','primary')}</div></div><div class="panel"><h2>Approval preview</h2><div id="pbPreview"><div class="empty">Your AI-generated project structure will appear here. Nothing is saved until you approve it.</div></div></div></div>`}
async function buildProjectAI(){$('pbPreview').innerHTML='<div class="empty">Building project proposal…</div>';await run(async()=>{let r=await api('ai-project-plan','POST',{prompt:val('pbPrompt')});window.v10plan=r;$('pbPreview').innerHTML=projectPlanHTML(r)})}
function projectPlanHTML(p){let tasks=(p.phases||[]).reduce((n,x)=>n+(x.tasks||[]).length,0);return `<div class="v9hero"><div class="eyebrow">Proposed project</div><h2>${esc(p.name||'Untitled')}</h2><p>${esc(p.description||'')}</p><div class="small muted">${(p.phases||[]).length} phases · ${tasks} tasks · ${(p.milestones||[]).length} milestones · ${(p.risks||[]).length} risks</div></div>${(p.phases||[]).map(ph=>`<div class="phase"><b>${esc(ph.title)}</b>${(ph.tasks||[]).map(t=>`<div class="listrow"><div>${esc(t.name)}<div class="small muted">${esc(t.priority||'medium')} · ${Number(t.duration_days||1)} day(s)${t.depends_on?' · after '+esc(t.depends_on):''}</div></div></div>`).join('')}</div>`).join('')}<h3>Milestones</h3>${(p.milestones||[]).map(m=>`<div class="small">◆ ${esc(m.title)}</div>`).join('')||'<div class="small muted">None</div>'}<h3 style="margin-top:12px">Risks</h3>${(p.risks||[]).map(r=>`<div class="small">! ${esc(r.title)} · ${esc(r.severity||'medium')}</div>`).join('')||'<div class="small muted">None</div>'}<div class="actions" style="margin-top:16px">${btn('Approve & create project','approveProjectAI()','primary')}</div>`}
async function approveProjectAI(){if(!window.v10plan)return;if(!confirm('Create this project, phases, tasks, dependencies, milestones and risks?'))return;await run(async()=>{let r=await api('ai-project-create','POST',{plan:window.v10plan,start_date:val('pbStart'),end_date:val('pbEnd')});toast('Project '+r.project_code+' created');await refresh();page='projects';projectId=r.id;tab='board';render()})}
function templatesV10(){$('main').innerHTML=title('Reusable project structures','Project Templates','Save a successful project structure and reuse it later.')+`<div class="panel">${S.project_templates.map(t=>`<div class="listrow"><div><b>${esc(t.title)}</b><div class="small muted">${esc(t.description||'')} · ${new Date(t.created_at).toLocaleDateString()}</div></div><div>${btn('Create project',`templateCreateModal('${t.id}')`,'primary')}${btn('Delete',`deleteTemplate('${t.id}')`,'danger')}</div></div>`).join('')||'<div class="empty">No templates yet. Open a project and choose Save as Template.</div>'}</div>`}
function templateCreateModal(id){let t=S.project_templates.find(x=>x.id===id);modal('Create from Template',`<div class="form"><label class="wide">Project name<input id="tcname" value="${esc((t?.title||'').replace(/ Template$/,''))}"></label><label>Start<input id="tcstart" type="date" value="${today()}"></label><label>Target<input id="tcend" type="date"></label></div><div class="actions">${btn('Cancel','closeModal()')}${btn('Create','createFromTemplate("'+id+'")','primary')}</div>`)}
async function createFromTemplate(id){await run(async()=>{let r=await api('templates/'+id+'/create-project','POST',{name:val('tcname'),start_date:val('tcstart'),end_date:val('tcend')});closeModal();await refresh();page='projects';projectId=r.id;render()})}
async function deleteTemplate(id){if(!confirm('Delete this template?'))return;await run(async()=>{await api('templates/'+id,'DELETE');await refresh()})}
async function saveTemplate(pid){let n=prompt('Template name',(P(pid)?.name||'Project')+' Template');if(!n)return;await run(async()=>{await api('templates/from-project','POST',{project_id:pid,title:n});await refresh();toast('Template saved')})}
function roadmapV10(){let ps=S.projects.filter(p=>p.status==='active'&&p.start_date&&p.end_date);let dates=ps.flatMap(p=>[new Date(p.start_date+'T12:00:00'),new Date(p.end_date+'T12:00:00')]);if(!dates.length){$('main').innerHTML=title('Portfolio timeline','Roadmap','Active projects across time.')+'<div class="empty">Add project start and target dates to build the roadmap.</div>';return}let min=new Date(Math.min(...dates)),max=new Date(Math.max(...dates)),span=Math.max(1,max-min);$('main').innerHTML=title('Portfolio timeline','Roadmap','Active projects across time.')+`<div class="panel">${ps.sort((a,b)=>a.start_date.localeCompare(b.start_date)).map(p=>{let l=(new Date(p.start_date+'T12:00:00')-min)/span*100,w=Math.max(2,(new Date(p.end_date+'T12:00:00')-new Date(p.start_date+'T12:00:00'))/span*100);return `<div style="margin:16px 0"><div class="between"><b class="click" onclick="openDetail('${p.id}')">${esc(p.project_code||'')} ${esc(p.name)}</b><span class="small muted">${esc(p.start_date)} → ${esc(p.end_date)}</span></div><div style="height:18px;background:#0a1220;border-radius:9px;position:relative;margin-top:6px"><i style="position:absolute;left:${l}%;width:${w}%;height:100%;background:linear-gradient(90deg,var(--cyan),var(--violet));border-radius:9px"></i></div></div>`}).join('')}</div>`}
function approvalsV10(){let a=S.approvals;$('main').innerHTML=title('Controlled decisions','Approvals','Review pending budget, schedule, change and closeout requests.')+`<div class="panel">${a.map(x=>`<div class="listrow"><div><b>${esc(x.title)}</b><div class="small muted">${esc(P(x.project_id)?.name||'')} · ${esc(x.kind)} · ${esc(x.status)} · ${fmt(x.amount)} · ${Number(x.schedule_days)>=0?'+':''}${x.schedule_days} days</div></div><div>${x.status==='pending'?btn('Approve',`decideApproval('${x.id}','approved')`,'primary')+btn('Reject',`decideApproval('${x.id}','rejected')`,'danger'):'<span class="pill">'+esc(x.status)+'</span>'}</div></div>`).join('')||'<div class="empty">No approvals.</div>'}</div>`}
async function decideApproval(id,status){await run(async()=>{await api('approvals/'+id,'PATCH',{status});await refresh()})}
function decisionModal(){modal('Record Decision',`<div class="form"><label class="wide">Title<input id="dectitle"></label><label>Status<select id="decstatus"><option>approved</option><option>pending</option><option>rejected</option></select></label><label>Decided by<input id="decby"></label><label>Date<input id="decdate" type="date" value="${today()}"></label><label class="wide">Decision / rationale<textarea id="dectext"></textarea></label></div><div class="actions">${btn('Cancel','closeModal()')}${btn('Save','saveDecision()','primary')}</div>`)}
async function saveDecision(){await run(async()=>{await api('decisions','POST',{project_id:projectId,title:val('dectitle'),status:val('decstatus'),decided_by:val('decby'),decision_date:val('decdate'),decision:val('dectext')});closeModal();await refresh()})}
function procurementModal(){modal('Procurement Item',`<div class="form"><label class="wide">Item<input id="pritem"></label><label>Vendor<input id="prvendor"></label><label>Status<select id="prstatus">${['planning','rfq','quotes','approval','po','ordered','delivered','closed'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>RFQ date<input id="prrfq" type="date"></label><label>Delivery<input id="prdelivery" type="date"></label><label>PO number<input id="prpo"></label><label>Amount<input id="pramount" type="number" step="0.01"></label><label class="wide">Notes<textarea id="prnotes"></textarea></label></div><div class="actions">${btn('Cancel','closeModal()')}${btn('Save','saveProcurement()','primary')}</div>`)}
async function saveProcurement(){await run(async()=>{await api('procurement','POST',{project_id:projectId,item:val('pritem'),vendor:val('prvendor'),status:val('prstatus'),rfq_date:val('prrfq'),delivery_date:val('prdelivery'),po_number:val('prpo'),amount:val('pramount'),notes:val('prnotes')});closeModal();await refresh()})}
function fieldReportModal(){modal('Daily Field Report',`<div class="form"><label>Date<input id="frdate" type="date" value="${today()}"></label><label>Contractor<input id="frcontractor"></label><label class="wide">Personnel on site<input id="frpeople"></label><label>Weather<input id="frweather"></label><label class="wide">Work completed<textarea id="frwork"></textarea></label><label class="wide">Issues encountered<textarea id="frissues"></textarea></label><label class="wide">Safety concerns<textarea id="frsafety"></textarea></label><label class="wide">Next work<textarea id="frnext"></textarea></label></div><div class="actions">${btn('Cancel','closeModal()')}${btn('Save report','saveFieldReport()','primary')}</div>`)}
async function saveFieldReport(){await run(async()=>{await api('field-reports','POST',{project_id:projectId,report_date:val('frdate'),contractor:val('frcontractor'),personnel:val('frpeople'),weather:val('frweather'),work_completed:val('frwork'),issues:val('frissues'),safety:val('frsafety'),next_work:val('frnext')});closeModal();await refresh()})}
async function criticalPathV10(pid){await run(async()=>{let r=await api('critical-path/'+pid);modal('Critical Path',`<p><b>Calculated dependency-chain duration: ${r.total_days} days</b></p>${r.tasks.map((t,i)=>`<div class="listrow"><div><span class="pill">${i+1}</span> ${esc(t.name)}</div><span>${t.duration_days} day(s)</span></div>`).join('')||'<div class="empty">No tasks.</div>'}<div class="small muted" style="margin-top:12px">V10 calculates the longest finish-to-start dependency chain using task durations. It is a planning aid, not a full CPM resource-leveling engine.</div>`)})}

const projectDetailV10Base=projectDetail;projectDetail=function(){projectDetailV10Base();let p=P(projectId);if(!p)return;let h=document.querySelector('#main h1');if(h&&p.project_code)h.insertAdjacentHTML('afterend',`<div class="small muted">${esc(p.project_code)}</div>`);let tabsEl=document.querySelector('#main .tabs');if(tabsEl){['decisions','procurement','fieldreports'].forEach(t=>tabsEl.insertAdjacentHTML('beforeend',`<button class="${tab===t?'active':''}" onclick="tab='${t}';render()">${t==='fieldreports'?'Field Reports':t[0].toUpperCase()+t.slice(1)}</button>`))}let top=document.querySelector('#main .top .actions');if(top)top.insertAdjacentHTML('beforeend',btn('Project Gantt',`projectGantt('${p.id}')`)+btn('Critical Path',`criticalPathV10('${p.id}')`)+btn('Save as Template',`saveTemplate('${p.id}')`));let pane=$('projectPane');if(!pane)return;if(tab==='decisions')pane.innerHTML=`<div class="panel"><div class="between"><h2>Decisions Register</h2>${btn('+ Decision','decisionModal()','primary')}</div>${S.decisions.filter(x=>x.project_id===p.id).map(x=>`<div class="phase"><b>${esc(x.decision_no)} · ${esc(x.title)}</b><div class="small muted">${esc(x.status)} · ${esc(x.decision_date||'')} · ${esc(x.decided_by||'')}</div><p>${esc(x.decision||'')}</p></div>`).join('')||'<div class="empty">No decisions recorded.</div>'}</div>`;else if(tab==='procurement')pane.innerHTML=`<div class="panel"><div class="between"><h2>Procurement Tracker</h2>${btn('+ Item','procurementModal()','primary')}</div>${S.procurement.filter(x=>x.project_id===p.id).map(x=>`<div class="listrow"><div><b>${esc(x.item)}</b><div class="small muted">${esc(x.status)} · ${esc(x.vendor||'No vendor')} · PO ${esc(x.po_number||'—')} · Delivery ${esc(x.delivery_date||'—')}</div></div><b>${fmt(x.amount)}</b></div>`).join('')||'<div class="empty">No procurement items.</div>'}</div>`;else if(tab==='fieldreports')pane.innerHTML=`<div class="panel"><div class="between"><h2>Field Reports</h2>${btn('+ Daily Report','fieldReportModal()','primary')}</div>${S.field_reports.filter(x=>x.project_id===p.id).map(x=>`<div class="phase"><b>${esc(x.report_date)} · ${esc(x.contractor||'Field report')}</b><div class="small muted">${esc(x.weather||'')} ${x.personnel?'· '+esc(x.personnel):''}</div><p><b>Work:</b> ${esc(x.work_completed||'')}</p>${x.issues?`<p><b>Issues:</b> ${esc(x.issues)}</p>`:''}${x.next_work?`<p><b>Next:</b> ${esc(x.next_work)}</p>`:''}</div>`).join('')||'<div class="empty">No field reports.</div>'}</div>`}

// JWorks 10.1 navigation polish
// JWorks 10.1.1: AI launcher is inside the authenticated shell and is always visible there.
const jworksNavActive=navActive;navActive=function(){jworksNavActive();document.querySelectorAll('#nav details').forEach(d=>{if(d.querySelector('button.active'))d.open=true})};

// ===== JWorks 10.2.11 Cloud · Scope of Work Builder =====
function sowSections(x){try{return Array.isArray(x.content_json)?x.content_json:JSON.parse(x.content_json||'[]')}catch(e){return []}}
function sowForProject(pid){return (S.scopes_of_work||[]).filter(x=>x.project_id===pid).sort((a,b)=>(b.updated_at||'').localeCompare(a.updated_at||''))}
function sowHome(pid){let list=sowForProject(pid);$('projectPane').innerHTML=`<div class="panel"><div class="between"><div><h2>Scope of Work</h2><div class="small muted">Build contractor-ready bid scopes manually, with AI, or using both.</div></div><div class="actions">${btn('+ Manual Scope',`newSow('${pid}','manual')`)}${btn('✦ AI Draft',`newSow('${pid}','ai')`,'primary')}</div></div>${list.map(x=>`<div class="listrow"><div class="click" onclick="editSow('${x.id}')"><b>${esc(x.title)}</b><div class="small muted">${esc(x.status)} · Rev ${Number(x.revision||0)} · ${esc(x.source_mode||'manual')} · updated ${new Date(x.updated_at).toLocaleString()}</div></div><div class="actions">${btn('Open',`editSow('${x.id}')`)}${btn('Print / PDF',`printSow('${x.id}')`)}${btn('Delete',`deleteSow('${x.id}')`,'danger')}</div></div>`).join('')||'<div class="empty">No scopes yet. Start manually or have AI prepare the first draft.</div>'}</div>`}
async function newSow(pid,mode){if(mode==='ai'){modal('AI Scope of Work Draft',`<p class="muted">Describe the job, constraints, known quantities, work hours, shutdowns, owner-supplied items and anything bidders must know. AI will mark unknown facts as [TO CONFIRM].</p><textarea id="sowPrompt" style="width:100%;min-height:180px" placeholder="Example: Replace the deteriorated ceiling and structural I-beams... Work Monday-Friday 9:30 PM-5:00 AM..."></textarea><div class="actions">${btn('Cancel','closeModal()')}${btn('Generate draft',`generateSowAI('${pid}')`,'primary')}</div>`);return}await run(async()=>{let r=await api('scopes','POST',{project_id:pid,source_mode:'manual'});await refresh();editSow(r.id)})}
async function generateSowAI(pid){let prompt=val('sowPrompt').trim();if(!prompt)return alert('Describe the work first.');let body=$('modalBody');if(body)body.innerHTML='<div class="empty">JWorks AI is drafting the scope…</div>';await run(async()=>{let draft=await api('scopes/ai-draft','POST',{project_id:pid,prompt});let r=await api('scopes','POST',{project_id:pid,title:draft.title,sections:draft.sections,source_mode:'ai',ai_prompt:prompt});closeModal();await refresh();editSow(r.id);if((draft.review_flags||[]).length)alert('AI review flags:\n\n• '+draft.review_flags.join('\n• '))})}
function sowRevisionHistory(x){try{let v=x.revision_history_json;return Array.isArray(v)?v:JSON.parse(v||'[]')}catch(e){return []}}
function sowHasConfirm(sections){return (sections||[]).some(s=>/\[TO CONFIRM\]/i.test(String(s.body||''))||/\[TO CONFIRM\]/i.test(String(s.title||'')))}
function editSow(id){let x=(S.scopes_of_work||[]).find(s=>s.id===id);if(!x)return;let sections=sowSections(x),p=P(x.project_id),hist=sowRevisionHistory(x),rev=String(x.revision_label??x.revision??'0'),rdate=x.revision_date||new Date().toISOString().slice(0,10),code=x.document_project_code||p?.project_code||'';window.activeSow={id,sections,revisionHistory:hist};modal('Scope of Work Builder',`<div class="sow-builder-head"><div class="form"><label class="wide">Document title<input id="sowTitle" value="${esc(x.title)}"></label><label>Status<select id="sowStatus">${['draft','internal_review','approved_for_bid','issued','awarded'].map(v=>`<option value="${v}" ${x.status===v?'selected':''}>${v.replaceAll('_',' ')}</option>`).join('')}</select></label><label>Creation mode<input value="${esc(x.source_mode||'manual')}" disabled></label><label>Document project code<input id="sowProjectCode" value="${esc(code)}" placeholder="e.g. DWT-26-014"></label><label>Revision<input id="sowRevision" value="${esc(rev)}" placeholder="0, 1, A, B..."></label><label>Revision date<input id="sowRevisionDate" type="date" value="${esc(rdate)}"></label></div><div class="small muted" style="margin-top:8px">Document project code is specific to this SOW and does not change the underlying JWorks project code.</div></div><div id="sowSections" class="sow-sections"></div><div class="panel" style="margin-top:14px"><div class="between"><div><h3 style="margin:0">Revision History</h3><div class="small muted">Saved document revisions shown on the contractor-facing SOW.</div></div>${btn('+ Add revision entry','addSowRevisionEntry()')}</div><div id="sowRevisionHistory"></div></div><div class="sow-builder-actions">${btn('+ Add section','addSowSection()')}${btn('Preview / Print PDF',`saveThenPrintSow('${id}')`)}${btn('Save',`saveSow('${id}')`,'primary')}</div>`);let d=document.querySelector('#modal .dialog');if(d)d.classList.add('sow-dialog');renderSowSections();renderSowRevisionHistory()}
function renderSowRevisionHistory(){let root=$('sowRevisionHistory');if(!root||!window.activeSow)return;let h=window.activeSow.revisionHistory||[];root.innerHTML=h.length?`<div style="overflow:auto;margin-top:10px"><table style="width:100%"><thead><tr><th>Rev.</th><th>Date</th><th>Description</th><th>Prepared By</th><th></th></tr></thead><tbody>${h.map((r,i)=>`<tr><td><input id="sowRhRev${i}" value="${esc(r.revision||'')}" style="min-width:70px"></td><td><input id="sowRhDate${i}" type="date" value="${esc(r.date||'')}"></td><td><input id="sowRhDesc${i}" value="${esc(r.description||'')}" placeholder="Issued for Bid"></td><td><input id="sowRhBy${i}" value="${esc(r.prepared_by||'')}"></td><td><button class="btn danger" onclick="removeSowRevisionEntry(${i})">Remove</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="small muted" style="margin-top:10px">No revision history entries yet.</div>'}
function syncSowRevisionHistory(){if(!window.activeSow)return;window.activeSow.revisionHistory=(window.activeSow.revisionHistory||[]).map((r,i)=>({revision:val('sowRhRev'+i),date:val('sowRhDate'+i),description:val('sowRhDesc'+i),prepared_by:val('sowRhBy'+i)}))}
function addSowRevisionEntry(){syncSowRevisionHistory();window.activeSow.revisionHistory.push({revision:val('sowRevision')||'0',date:val('sowRevisionDate')||new Date().toISOString().slice(0,10),description:'Issued for Bid',prepared_by:(window.AUTH&&AUTH.username)||''});renderSowRevisionHistory()}
function removeSowRevisionEntry(i){syncSowRevisionHistory();window.activeSow.revisionHistory.splice(i,1);renderSowRevisionHistory()}
function autoGrowSow(el){if(!el)return;el.style.height='auto';el.style.height=Math.max(150,el.scrollHeight+2)+'px'}
function renderSowSections(){let root=$('sowSections');if(!root||!window.activeSow)return;root.innerHTML=window.activeSow.sections.map((s,i)=>`<section class="sow-card"><div class="sow-card-top"><div><span class="sow-section-kicker">SECTION ${String(i+1).padStart(2,'0')}</span><strong>${esc(s.title||'Untitled section')}</strong></div><div class="sow-card-actions"><button class="btn sow-icon" title="Move section up" onclick="moveSowSection(${i},-1)" ${i===0?'disabled':''}>↑</button><button class="btn sow-icon" title="Move section down" onclick="moveSowSection(${i},1)" ${i===window.activeSow.sections.length-1?'disabled':''}>↓</button><button class="btn danger" onclick="removeSowSection(${i})">Remove</button></div></div><div class="sow-field"><label for="sowH${i}">Heading</label><input id="sowH${i}" value="${esc(s.title||'')}" oninput="this.closest('.sow-card').querySelector('.sow-card-top strong').textContent=this.value||'Untitled section'"></div><div class="sow-field"><label for="sowB${i}">Content</label><textarea id="sowB${i}" oninput="autoGrowSow(this)">${esc(s.body||'')}</textarea></div></section>`).join('');root.querySelectorAll('textarea').forEach(autoGrowSow)}
function syncSow(){if(!window.activeSow)return;window.activeSow.sections.forEach((s,i)=>{let h=$('sowH'+i),b=$('sowB'+i);if(h)s.title=h.value;if(b)s.body=b.value})}
function addSowSection(){syncSow();window.activeSow.sections.push({title:'New Section',body:''});renderSowSections();setTimeout(()=>{let el=$('sowH'+(window.activeSow.sections.length-1));if(el){el.scrollIntoView({behavior:'smooth',block:'center'});el.select()}},50)}
function removeSowSection(i){syncSow();if(window.activeSow.sections.length>1&&!confirm('Remove this section?'))return;window.activeSow.sections.splice(i,1);renderSowSections()}
function moveSowSection(i,d){syncSow();let j=i+d;if(j<0||j>=window.activeSow.sections.length)return;[window.activeSow.sections[i],window.activeSow.sections[j]]=[window.activeSow.sections[j],window.activeSow.sections[i]];renderSowSections()}
async function saveSow(id,quiet=false){syncSow();syncSowRevisionHistory();let status=val('sowStatus'),hasConfirm=sowHasConfirm(window.activeSow.sections);if(['approved_for_bid','issued','awarded'].includes(status)&&hasConfirm){alert('This SOW still contains unresolved [TO CONFIRM] items. Resolve them before approving or issuing the document to contractors.');throw new Error('Unresolved [TO CONFIRM] items')}let payload={title:val('sowTitle'),status,sections:window.activeSow.sections,document_project_code:val('sowProjectCode').trim(),revision_label:val('sowRevision').trim()||'0',revision_date:val('sowRevisionDate'),revision_history_json:JSON.stringify(window.activeSow.revisionHistory||[])};await api('scopes/'+id,'PATCH',payload);await refresh();if(!quiet)toast('Scope saved')}
async function saveThenPrintSow(id){await run(async()=>{await saveSow(id,true);printSow(id)})}
function sowPrintBody(body){let safe=esc(body||'');safe=safe.replace(/\[TO CONFIRM\]/g,'<span class="confirm">[TO CONFIRM]</span>');return safe}
