async function reportStyleChooser1032(pid){let saved=[];try{let x=await api('report-templates');saved=x.items||[]}catch(e){};modal('Generate Report',`<div class="report-style-grid">${[['quick','Quick / Internal','Fast, compact and ideal for your own notes.'],['executive','Executive Summary','One-page management-oriented snapshot.'],['professional','Professional','Polished project update for meetings and presentations.'],['formal','Formal Project Report','Document-control style layout for official distribution.']].map(x=>`<button class="report-style" onclick="closeModal();renderStyledReport1032('${pid}','${x[0]}')"><b>${x[1]}</b><span>${x[2]}</span></button>`).join('')}</div>${saved.length?`<h3 style="margin-top:18px">My saved styles</h3>${saved.map(r=>`<button class="report-style saved-report" onclick='closeModal();renderStyledReport1032("${pid}","custom",${JSON.stringify(r.config_json||'{}')})'><b>${esc(r.title)}</b><span>Saved custom report template</span></button>`).join('')}`:''}<div class="actions">${btn('Cancel','closeModal()')}</div>`)}
function renderStyledReport1032(id,style='professional',configRaw=null){let p=P(id),f=projectFacts(id);if(!p)return;let cfg={tasks:true,milestones:true,risks:true,costs:true,decisions:true,field_reports:false,cover:true,page_footer:true};if(configRaw){try{Object.assign(cfg,JSON.parse(configRaw));style=cfg.style||style}catch(e){}}let issues=(S.issues||[]).filter(x=>x.project_id===id&&x.status==='open'),tasks=f.open.slice(0,12),ms=f.ms||[],dec=(S.decisions||[]).filter(x=>x.project_id===id).slice(0,8),fr=(S.field_reports||[]).filter(x=>x.project_id===id).slice(0,5),generated=new Date().toLocaleString();let compact=style==='quick',exec=style==='executive',formal=style==='formal';let w=window.open('','_blank');let section=(name,html)=>`<section><h2>${name}</h2>${html}</section>`;let table=(head,body)=>`<table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${head.length}">None</td></tr>`}</tbody></table>`;let body='';body+=section('Project Snapshot',`<div class="kpis"><div><b>${f.pct}%</b><span>Complete</span></div><div><b>${f.over.length}</b><span>Overdue</span></div><div><b>${f.blockedN.length}</b><span>Dependencies</span></div><div><b>${f.days===null?'—':f.days}</b><span>Days to target</span></div></div><p>${esc(p.description||'No project summary entered.')}</p>`);if(cfg.tasks)body+=section('Current Work',table(['Task','Status','Due'],tasks.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.status)}</td><td>${esc(t.due_date||'—')}</td></tr>`).join('')));if(cfg.milestones&&!compact)body+=section('Milestones',table(['Milestone','Target','Status'],ms.map(m=>`<tr><td>${esc(m.title)}</td><td>${esc(m.due_date||'—')}</td><td>${m.done?'Complete':'Open'}</td></tr>`).join('')));if(cfg.risks)body+=section('Risks & Issues',table(['Item','Severity','Owner'],issues.map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(x.severity)}</td><td>${esc(x.owner_name||'—')}</td></tr>`).join('')));if(cfg.costs&&!compact)body+=section('Financial Summary',table(['Budget','Committed','Spent'],`<tr><td>${fmt(p.estimated_cost)}</td><td>${fmt(f.committed)}</td><td>${fmt(f.spent)}</td></tr>`));if(cfg.decisions&&!exec&&!compact)body+=section('Recent Decisions',table(['Decision','Status','Date'],dec.map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(x.status)}</td><td>${esc(x.decision_date||'—')}</td></tr>`).join('')));if(cfg.field_reports&&formal)body+=section('Field Reports',fr.map(x=>`<div class="note"><b>${esc(x.report_date)} · ${esc(x.contractor||'Field report')}</b><p>${esc(x.work_completed||'')}</p></div>`).join('')||'<p>None</p>');let cls='style-'+style;w.document.write(`<!doctype html><html><head><title>${esc(p.name)} - Report</title><style>@page{size:letter;margin:${compact?'.35in':'.55in'}}*{box-sizing:border-box}body{font:12px Segoe UI,Arial;color:#1f2937;margin:0;background:#fff}.doc{max-width:8.5in;margin:auto}.cover{padding:${formal?'34px 0 28px':'20px 0'};border-bottom:${formal?'6px solid #17324d':'3px solid #26758d'};margin-bottom:20px}.brand{font-size:11px;font-weight:900;letter-spacing:.18em;color:#26758d}.cover h1{font-size:${formal?'30px':'25px'};margin:7px 0}.meta{color:#64748b}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.kpis div{border:1px solid #dbe4ec;padding:10px;border-radius:${formal?'2px':'8px'}}.kpis b{font-size:19px;display:block;color:#17324d}.kpis span{font-size:10px;color:#64748b}section{margin:${compact?'12px':'20px'} 0;break-inside:avoid}h2{font-size:${compact?'12px':'14px'};text-transform:uppercase;letter-spacing:.08em;border-bottom:1px solid #cbd5e1;padding-bottom:5px;color:#17324d}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:${compact?'5px':'7px'};border-bottom:1px solid #e2e8f0}th{font-size:9px;text-transform:uppercase;color:#64748b}.style-executive section{margin:13px 0}.style-formal .cover:before{content:'PROJECT REPORT';display:block;font-size:9px;letter-spacing:.25em;color:#64748b}.style-quick .cover{padding:10px 0;margin-bottom:10px}.style-quick .cover h1{font-size:20px}.note{border-left:3px solid #26758d;padding-left:10px}.footer{margin-top:28px;border-top:1px solid #cbd5e1;padding-top:8px;color:#64748b;font-size:9px}.screen{position:fixed;right:18px;top:18px;padding:9px 13px}@media print{.screen{display:none}}</style></head><body><button class="screen" onclick="window.print()">Print / Save PDF</button><div class="doc ${cls}"><div class="cover"><div class="brand">JWORKS</div><h1>${formal?'Formal Project Report':exec?'Executive Project Summary':compact?'Internal Project Update':'Project Status Report'}</h1><div>${esc(p.name)}</div><div class="meta">${esc(p.project_code||'')} · ${esc(p.status)} · Prepared ${esc(generated)}</div></div>${body}${cfg.page_footer?`<div class="footer">JWorks · ${esc(p.name)} · ${esc(generated)}</div>`:''}</div></body></html>`);w.document.close()}

