const bootV11Base=boot;boot=async function(){let s=await api('session?cb='+Date.now());JW11.session=s;if(!s.authenticated){$('marketing')?.classList.remove('hidden');let n=await api('setup-needed?cb='+Date.now());$('authTitle').textContent=n.needed?'Create JWorks owner':'Sign in to JWorks';$('authText').textContent=n.needed?'First run: create the JWorks Platform Owner.':'Enter your Company ID and account credentials.';$('authEyebrow').textContent=n.needed?'JWorks V11 platform setup':'Secure company workspace';$('authForm').dataset.mode=n.needed?'setup':'login';$('companyIdLabel').classList.toggle('hidden',!!n.needed);$('companyId').required=!n.needed;return}$('marketing')?.classList.add('hidden');$('auth').classList.add('hidden');$('shell').classList.remove('hidden');csrf=s.csrf;$('who').innerHTML=`<b>${esc(s.company_name||'JWorks')}</b><div class="small muted">${esc(s.username)} · ${esc((s.role||'user').replace('_',' '))}</div>`;$('platformNav')?.classList.toggle('hidden',s.role!=='platform_owner');if(s.role!=='platform_owner'&&page==='platform')page='dashboard';await refresh()}
