function trialV11(){document.querySelector('#auth .panel').innerHTML=`<div class="brand">J<b>WORKS</b> <span class="small">V11 CLOUD</span></div><div class="eyebrow">14-day free trial</div><h1>Create your company workspace</h1><p class="sub">Includes 5 user seats for 14 days.</p><form id="trialForm"><label>Company name<input id="trialCompany" required></label><label>Administrator username<input id="trialUser" required minlength="3"></label><label>Password<input id="trialPass" type="password" required></label><p id="trialError" class="error"></p><button class="btn primary" style="width:100%">Start free trial</button><button type="button" class="btn" style="width:100%;margin-top:8px" onclick="location.reload()">Back to sign in</button></form>`;$('trialForm').onsubmit=async e=>{e.preventDefault();try{let x=await api('trial','POST',{company_name:val('trialCompany'),username:val('trialUser'),password:val('trialPass')});document.querySelector('#auth .panel').innerHTML=`<div class="brand">J<b>WORKS</b></div><div class="eyebrow">Workspace ready</div><h1>${esc(val('trialCompany')||'Your company')}</h1><p>Your 14-day trial is ready. Save this Company ID — your team will use it to sign in.</p><div class="panel" style="text-align:center"><div class="small muted">COMPANY ID</div><h2 style="font-size:28px;letter-spacing:.08em">${esc(x.company_id)}</h2></div><button class="btn primary" style="width:100%" onclick="location.reload()">Go to sign in</button>`}catch(err){$('trialError').textContent=err.message}}}

