async function companyPortalV11(){try{let [c,u]=await Promise.all([api('company'),api('company-users').catch(()=>({users:[]}))]);JW11.company=c.company;let co=c.company,users=u.users||[],used=users.filter(x=>x.status==='active').length,pct=Math.min(100,Math.round(used/Math.max(1,Number(co.seat_limit))*100));$('main').innerHTML=title('Organization','Company Portal','Manage your JWorks workspace, licenses, branding and users.',c.role==='platform_owner'?btn('JWorks Owner Portal',"page='platform';render()",'primary'):'')+`<div class="panel"><div class="between"><div class="company-brand">${co.logo_data_url?`<img class="company-logo" src="${esc(co.logo_data_url)}">`:''}<div><div class="eyebrow">${esc(co.login_code)}</div><h2>${esc(co.name)}</h2><div class="muted">${esc(co.plan)} · ${esc(co.status)}</div></div></div><span class="pill">${used} / ${co.seat_limit} licenses</span></div><div class="licensebar" style="margin-top:15px"><i style="width:${pct}%"></i></div>${co.trial_ends_at?`<p class="small muted">Trial ends ${esc(co.trial_ends_at.slice(0,10))}</p>`:''}</div><div class="grid"><div class="panel"><div class="between"><h2>Users</h2>${['admin','platform_owner'].includes(c.role)?btn('+ Add User','addCompanyUserV11()','primary'):''}</div>${users.length?`<table class="company-table"><tr><th>User</th><th>Role</th><th>Status</th></tr>${users.map(x=>`<tr><td>${esc(x.username)}</td><td><span class="rolebadge">${esc(x.role)}</span></td><td>${esc(x.status)}</td><td>${['admin','platform_owner'].includes(c.role)?btn('Manage',`editCompanyUserV111('${x.id}','${esc(x.username)}','${x.role}','${x.status}')`):''}</td></tr>`).join('')}</table>`:'<div class="empty">User administration requires Company Administrator access.</div>'}</div><div class="panel"><h2>Company Branding</h2><p class="muted">Used on JWorks-generated reports and Scopes of Work while retaining JWorks attribution.</p><label>Company name<input id="coName" value="${esc(co.name)}"></label><label>Address / contact<textarea id="coAddress">${esc(co.address||'')}</textarea></label><label>Report footer<input id="coFooter" value="${esc(co.report_footer||'Generated with JWorks')}"></label><label>Company logo<input id="coLogo" type="file" accept="image/png,image/jpeg,image/webp" onchange="previewCompanyLogoV11(this)"></label><input type="hidden" id="coLogoData" value="${esc(co.logo_data_url||'')}"><div id="coLogoPreview">${co.logo_data_url?`<img class="company-logo" src="${esc(co.logo_data_url)}">`:''}</div><p>${btn('Save Branding','saveCompanyV11()','primary')}</p></div></div>`}catch(e){$('main').innerHTML=title('Organization','Company Portal')+`<div class="panel error">${esc(e.message)}</div>`}}
