async function platformPortalV11(){try{let x=await api('platform/companies'),cs=x.companies||[],seats=cs.reduce((a,c)=>a+Number(c.seat_limit||0),0),used=cs.reduce((a,c)=>a+Number(c.seats_used||0),0);$('main').innerHTML=title('JWorks Platform','Owner Portal','Manage customer companies, subscriptions, licenses and workspaces.',btn('+ Company','newPlatformCompanyV11()','primary'))+`<div class="metrics"><div class="metric"><strong>${cs.filter(c=>c.status==='active').length}</strong><span>Active companies</span></div><div class="metric"><strong>${used} / ${seats}</strong><span>Licensed users</span></div><div class="metric"><strong>${cs.filter(c=>c.status==='trial').length}</strong><span>Trials</span></div><div class="metric"><strong>${cs.reduce((a,c)=>a+Number(c.projects||0),0)}</strong><span>Projects</span></div></div><div class="panel"><h2>Companies</h2><table class="company-table"><tr><th>Company</th><th>Company ID</th><th>Plan</th><th>Seats</th><th>Status</th><th></th></tr>${cs.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.login_code)}</td><td>${esc(c.plan)}</td><td>${c.seats_used}/${c.seat_limit}</td><td>${esc(c.status)}</td><td>${btn('Manage',`managePlatformCompanyV11('${c.id}')`)}</td></tr>`).join('')}</table></div>`}catch(e){$('main').innerHTML=title('JWorks Platform','Owner Portal')+`<div class="panel error">${esc(e.message)}</div>`}}
