// Add company identity to generated project reports.
const renderStyledReportV11Base=renderStyledReport1032;
renderStyledReport1032=async function(id,style='professional',configRaw=null){
  try{let c=await api('company');JW11.company=c.company}catch(e){}
  let p=P(id); if(!p)return; let co=JW11.company||{};
  let w=window.open('','_blank'), oldOpen=window.open; window.open=()=>w;
  try{
    renderStyledReportV11Base(id,style,configRaw);
    setTimeout(()=>{try{
      let cover=w.document.querySelector('.cover');
      let logo=co.logo_data_url?`<img src="${co.logo_data_url}" style="max-width:150px;max-height:65px;object-fit:contain">`:'';
      if(cover)cover.insertAdjacentHTML('afterbegin',`<div style="display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:14px"><div>${logo}<div style="font-weight:800;font-size:14px">${esc(co.name||'')}</div></div><div style="text-align:right;font-size:10px;color:#64748b">Powered by JWorks</div></div>`);
      let foot=w.document.querySelector('.footer'); if(foot)foot.textContent=(co.report_footer||'Generated with JWorks')+' · '+p.name;
    }catch(e){}},80);
  } finally { window.open=oldOpen; }
}

