function v12Health(p){let f=projectFacts(p.id),score=100;score-=Math.min(30,f.over.length*7);score-=Math.min(20,f.blockedN.length*8);if(f.days!==null&&f.days<14&&f.pct<80)score-=12;if(p.budget&&f.committed>Number(p.budget))score-=15;return Math.max(0,Math.round(score))}
function intelligenceV12(){let active=S.projects.filter(p=>p.status==='active').map(p=>({p,score:v12Health(p),f:projectFacts(p.id)})).sort((a,b)=>a.score-b.score),over=S.tasks.filter(t=>t.status!=='done'&&t.due_date&&t.due_date<today());$('main').innerHTML=title('JWorks Intelligence','Project Pulse','What deserves your attention right now.')+`<div class="metrics"><div class="metric"><strong>${active.length?Math.round(active.reduce((a,x)=>a+x.score,0)/active.length):100}</strong><span>Portfolio health</span></div><div class="metric"><strong>${active.filter(x=>x.score<70).length}</strong><span>Projects at risk</span></div><div class="metric"><strong>${over.length}</strong><span>Overdue tasks</span></div><div class="metric"><strong>${(S.approvals||[]).filter(x=>x.status==='pending').length}</strong><span>Approvals waiting</span></div><div class="metric"><strong>${S.milestones.filter(m=>!m.done&&m.due_date&&m.due_date<=iso(new Date(Date.now()+14*86400000))).length}</strong><span>Milestones · 14 days</span></div></div><div class="grid"><div class="panel"><h2>Needs attention</h2>${active.slice(0,8).map(x=>`<div class="listrow"><div class="click" onclick="openDetail('${x.p.id}')"><b>${esc(x.p.name)}</b><div class="small muted">${x.f.over.length} overdue · ${x.f.blockedN.length} dependencies · ${x.f.pct}% complete</div></div><div class="health-ring">${x.score}</div></div>`).join('')||'<div class="empty">No active projects.</div>'}</div><div class="panel"><h2>Morning brief</h2><p>${active[0]&&active[0].score<80?`Start with <b>${esc(active[0].p.name)}</b>. Its health score is ${active[0].score} and it has ${active[0].f.over.length} overdue task(s).`:'Your active portfolio has no major calculated exceptions right now.'}</p><h3 style="margin-top:24px">What changed</h3><p class="muted">${S.activity.slice(-8).length} recent activity records are available across your workspace.</p>${btn('Open approvals',"page='approvals';render()")}</div></div>`}
function heatmapV12(){let ps=S.projects.filter(p=>p.status==='active');$('main').innerHTML=title('Portfolio intelligence','Heat Map','Health × priority across active projects.')+`<div class="panel" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px">${ps.map(p=>{let h=v12Health(p);return `<div class="setting-card click" onclick="openDetail('${p.id}')"><div class="between"><b>${esc(p.name)}</b><strong class="health-ring" style="font-size:28px">${h}</strong></div><div class="small muted">${esc(p.priority||'normal')} priority · ${projectStats(p.id).pct}% complete</div></div>`}).join('')||'<div class="empty">No active projects.</div>'}</div>`}
