function supportV12(){let articles=[['Getting Started','Set up your workspace, projects and team.'],['Importing from Excel','Move existing project and task trackers into JWorks.'],['Projects & Tasks','Plan, assign and track work.'],['SOW & Document Control','Build controlled contractor-ready scopes.'],['JWorks Intelligence','Understand Project Pulse, health and Autopilot.'],['Company Administration','Branding, users, modules and permissions.']];$('main').innerHTML=title('Help','Support Center','Knowledge, guidance and a direct line to JWorks support.')+`<div class="grid"><div class="panel"><h2>Knowledge Base</h2><input id="kbSearch" placeholder="Search JWorks help…" style="width:100%;margin-bottom:12px" oninput="document.querySelectorAll('.kbitem').forEach(x=>x.classList.toggle('hidden',!x.innerText.toLowerCase().includes(this.value.toLowerCase())))">${articles.map(a=>`<div class="listrow kbitem"><div><b>${a[0]}</b><div class="small muted">${a[1]}</div></div><span>→</span></div>`).join('')}</div><div class="panel"><h2>Contact Support</h2><label>Subject<input id="supSubject" style="width:100%"></label><label>Category<select id="supCategory" style="width:100%"><option>General</option><option>Technical issue</option><option>Billing</option><option>Feature request</option></select></label><label>Priority<select id="supPriority" style="width:100%"><option>Normal</option><option>High</option><option>Urgent</option></select></label><label>Description<textarea id="supBody" style="width:100%"></textarea></label><label><input type="checkbox" id="supDiag" checked> Include safe diagnostics (version, browser, current page)</label><p>${btn('Send support request','sendSupportV12()','primary')}</p><div id="supportResult" class="small muted"></div></div></div>`}
