function settingsV12(){settingsV10?.();setTimeout(()=>{let m=$('main');if(!m)return;let x=document.createElement('div');x.className='panel';x.style.marginTop='16px';x.innerHTML=`<h2>V12 Workspace Preferences</h2><div class="settings-grid"><div class="setting-card"><h3>Navigation</h3><p class="muted">Projects and Plan & Review are collapsible. Your sidebar choices are remembered automatically.</p></div><div class="setting-card"><h3>Release experience</h3><label><input type="checkbox" ${localStorage.getItem('jw_release_tours')!=='0'?'checked':''} onchange="localStorage.setItem('jw_release_tours',this.checked?'1':'0')"> Show What’s New after major updates</label></div><div class="setting-card"><h3>AI style</h3><select onchange="localStorage.setItem('jw_ai_style',this.value)"><option>Concise</option><option selected>Standard</option><option>Detailed</option></select></div><div class="setting-card"><h3>Regional</h3><select onchange="localStorage.setItem('jw_week_start',this.value)"><option>Monday</option><option>Sunday</option></select><p class="small muted">Currency: CAD · timezone follows device.</p></div></div>`;m.appendChild(x)},0)}
