function whatsNewModalV1201(){if(localStorage.getItem('jw_release_tours')==='0'||localStorage.getItem('jw_last_release')===JW_VERSION)return;let d=document.createElement('div');d.id='whatsNewModal';d.className='modal';d.innerHTML=`<div class="modalcard" style="max-width:760px"><div class="eyebrow">WELCOME TO JWORKS ${JW_VERSION}</div><h1>There’s a lot that’s new.</h1><p class="muted">V12 turns JWorks into a more complete commercial workspace while making everyday project management easier.</p><div class="grid" style="margin-top:18px"><div class="setting-card"><b>✦ Project Intelligence</b><p class="small muted">Project Pulse, health scoring, What Changed and early risk signals.</p></div><div class="setting-card"><b>◆ Your Company, Your JWorks</b><p class="small muted">Company branding, module controls and Powered by JWorks documents.</p></div><div class="setting-card"><b>▰ Better Planning</b><p class="small muted">Roadmap, Excel migration and improved portfolio visibility.</p></div><div class="setting-card"><b>⌁ Mobile + Support</b><p class="small muted">Cleaner mobile navigation, Sign Out and the new Support Center.</p></div></div><div class="actions" style="margin-top:18px"><button class="btn primary" onclick="localStorage.setItem('jw_last_release',JW_VERSION);this.closest('.modal').remove();page='whatsnew';render()">Explore What’s New</button><button class="btn" onclick="localStorage.setItem('jw_last_release',JW_VERSION);this.closest('.modal').remove()">Skip to Dashboard</button></div></div>`;document.body.appendChild(d)}
function armIdleV1201(minutes=10){clearTimeout(jwIdleTimer);clearTimeout(jwIdleWarn);let ms=Math.max(2,Number(minutes)||10)*60000;jwIdleWarn=setTimeout(()=>idleWarningV1201(),Math.max(1000,ms-60000));jwIdleTimer=setTimeout(()=>{api('logout','POST').catch(()=>{}).finally(()=>location.reload())},ms)}
function idleWarningV1201(){if(document.getElementById('idleV1201'))return;let d=document.createElement('div');d.id='idleV1201';d.className='modal';d.innerHTML=`<div class="modalcard" style="max-width:460px"><div class="eyebrow">SECURITY</div><h2>Still there?</h2><p>You’ll be signed out in about 60 seconds because there hasn’t been any activity.</p><button class="btn primary" onclick="this.closest('.modal').remove();armIdleV1201(jwSessionV1201?.inactivity_minutes||10)">Stay Signed In</button></div>`;document.body.appendChild(d)}
['pointerdown','keydown','touchstart','scroll'].forEach(ev=>document.addEventListener(ev,()=>{if(!document.getElementById('shell')?.classList.contains('hidden'))armIdleV1201(jwSessionV1201?.inactivity_minutes||10)},{passive:true}));
setTimeout(async()=>{let s=await sessionV1201();if(s?.authenticated){armIdleV1201(s.inactivity_minutes||10);setTimeout(whatsNewModalV1201,500)}},900);

async function companyV1201(){try{let [r,u]=await Promise.all([api('company'),api('company-users').catch(()=>({users:[]}))]);let c=r.company||{}, users=u.users||[], admin=['admin','platform_owner'].includes(r.role);let flags={};try{flags=JSON.parse(c.feature_flags||'{}')}catch(e){};$('main').innerHTML=title('Organization','Company Portal','Brand your workspace, manage people, security and the JWorks modules your company uses.')+`<div class="grid"><div class="panel"><div class="between"><div><div class="eyebrow">${esc(c.login_code||'')}</div><h2>${esc(c.name||'Company')}</h2><div class="muted">${esc(c.plan||'')} · ${esc(c.status||'')}</div></div>${c.logo_data_url?`<img class="company-logo" src="${esc(c.logo_data_url)}">`:''}</div><p class="small muted">${users.filter(x=>x.status==='active').length} / ${c.seat_limit||0} active seats</p></div><div class="panel"><h2>Branding & Appearance</h2><label>Company name<input id="coName12" value="${esc(c.name||'')}" ${admin?'':'disabled'}></label><label>Accent colour<input type="color" id="coAccent12" value="${esc(c.accent_color||'#5ee6e6')}" ${admin?'':'disabled'}></label><label>Company logo<input type="file" id="coLogo12" accept="image/png,image/jpeg,image/webp" ${admin?'':'disabled'}></label><label>Document branding<select id="coDocBrand12" ${admin?'':'disabled'}><option value="powered_by_jworks">Company logo + Powered by JWorks</option><option value="company">Company logo only</option><option value="jworks">JWorks standard</option></select></label><label>Report footer<input id="coFooter12" value="${esc(c.report_footer||'')}" ${admin?'':'disabled'}></label>${admin?`<p>${btn('Save Company Branding','saveCompanyV1201()','primary')}</p>`:''}</div></div><div class="grid"><div class="panel"><h2>Security</h2><label>Automatic sign out after inactivity<select id="coIdle12" ${admin?'':'disabled'}>${[10,15,30,60].map(n=>`<option value="${n}" ${Number(c.inactivity_minutes||10)===n?'selected':''}>${n} minutes</option>`).join('')}</select></label><p class="small muted">Users receive a warning one minute before sign out.</p><label>Support notification email<input id="coSupport12" type="email" value="${esc(c.support_email||'')}" placeholder="support@yourcompany.com" ${admin?'':'disabled'}></label>${admin?`<p>${btn('Save Security & Support','saveCompanyV1201()','primary')}</p>`:''}</div><div class="panel"><h2>Features & Modules</h2><p class="muted">Turn advanced JWorks capabilities on or off for this company.</p><div class="toggle-list">${V12_FEATURES.map(f=>`<label><span>${f.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}</span><input type="checkbox" data-company-feature="${f}" ${flags[f]===false?'':'checked'} ${admin?'':'disabled'}></label>`).join('')}</div>${admin?`<p>${btn('Save Module Settings','saveCompanyV1201()','primary')}</p>`:''}</div></div><div class="panel"><div class="between"><h2>Users</h2>${admin?btn('+ Add User','addCompanyUserV11()','primary'):''}</div>${users.map(x=>`<div class="listrow"><div><b>${esc(x.username)}</b><div class="small muted">${esc(x.role)} · ${esc(x.status)}</div></div>${admin?btn('Manage',`editCompanyUserV111('${x.id}','${esc(x.username)}','${x.role}','${x.status}')`):''}</div>`).join('')||'<div class="empty">No users found.</div>'}</div>`;$('coDocBrand12').value=c.document_branding||'powered_by_jworks'}catch(e){$('main').innerHTML=title('Organization','Company Portal')+`<div class="panel error">${esc(e.message)}</div>`}}
async function saveCompanyV1201(){let payload={name:val('coName12'),accent_color:val('coAccent12'),report_footer:val('coFooter12'),document_branding:val('coDocBrand12'),support_email:val('coSupport12'),inactivity_minutes:Number(val('coIdle12')||10)};let f=$('coLogo12')?.files?.[0];if(f){if(f.size>700000)return alert('Please keep the logo under 700 KB.');payload.logo_data_url=await new Promise(ok=>{let r=new FileReader();r.onload=()=>ok(r.result);r.readAsDataURL(f)})}let flags={};document.querySelectorAll('[data-company-feature]').forEach(x=>flags[x.dataset.companyFeature]=x.checked);payload.feature_flags=JSON.stringify(flags);await run(async()=>{await api('company','PATCH',payload);toast('Company settings saved');await companyV1201()})}

async function settingsV1201(){let r={settings:{}};try{r=await api('preferences')}catch(e){}let p=r.settings||{};$('main').innerHTML=title('Personalize JWorks','Settings','Choose how JWorks works for you. Company-wide branding, security and modules live in Company Portal.')+`<div class="settings-grid"><section class="setting-card"><h2>Workspace</h2><label>Default landing page<select id="setLanding12"><option value="dashboard">Command Center</option><option value="today">My Work</option><option value="projects">Projects</option><option value="intelligence">Intelligence Center</option><option value="roadmap">Roadmap</option></select></label><label>Density<select id="setDensity12"><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></label><label><input type="checkbox" id="setTours12" ${p.releaseTours===false?'':'checked'}> Show What’s New after releases</label></section><section class="setting-card"><h2>AI Preferences</h2><label>Response detail<select id="setAi12"><option>Concise</option><option>Standard</option><option>Detailed</option></select></label><label>AI change behavior<select id="setAiAction12"><option>Suggest only</option><option>Prepare for approval</option></select></label></section><section class="setting-card"><h2>Mobile</h2><p class="muted">Choose what appears in your mobile shortcut bar.</p><label>Shortcut 1<select id="mob112"><option value="dashboard">Home</option><option value="projects">Projects</option><option value="today">My Work</option><option value="intelligence">Intelligence</option></select></label><label>Shortcut 2<select id="mob212"><option value="projects">Projects</option><option value="today">My Work</option><option value="roadmap">Roadmap</option><option value="intelligence">Intelligence</option></select></label></section><section class="setting-card"><h2>Regional</h2><label>Currency<select id="currency12"><option>CAD</option><option>USD</option><option>EUR</option><option>GBP</option></select></label><label>Week starts<select id="week12"><option>Monday</option><option>Sunday</option></select></label></section><section class="setting-card setting-wide"><div class="between"><div><h2>Company configuration</h2><p class="muted">Logos, Powered by JWorks, module switches, support email and inactivity timeout are managed in Company Portal.</p></div>${btn('Open Company Portal',`page='company';render()`,'primary')}</div></section><section class="setting-card setting-wide">${btn('Save Settings','saveSettingsV1201()','primary')}</section></div>`;let set=(id,v)=>{if($(id)&&v!=null)$(id).value=v};set('setLanding12',p.landing);set('setDensity12',p.density);set('setAi12',p.aiDetail);set('setAiAction12',p.aiAction);set('mob112',p.mobile1);set('mob212',p.mobile2);set('currency12',p.currency);set('week12',p.weekStart)}
async function saveSettingsV1201(){let settings={landing:val('setLanding12'),density:val('setDensity12'),releaseTours:$('setTours12').checked,aiDetail:val('setAi12'),aiAction:val('setAiAction12'),mobile1:val('mob112'),mobile2:val('mob212'),currency:val('currency12'),weekStart:val('week12')};await run(async()=>{await api('preferences','PUT',{settings});localStorage.setItem('jw_release_tours',settings.releaseTours?'1':'0');toast('Settings saved')})}

// Replace the V12 wrappers with stable V12.0.1 pages.
const renderV1201Base=render;render=function(){if(page==='company')return companyV1201();if(page==='settings')return settingsV1201();return renderV1201Base()}

// V12.0.2: enforce signed-out public/mobile state and signed-in workspace navigation.
const bootV1202Base=boot;boot=async function(){await bootV1202Base();let signedIn=!document.getElementById('shell')?.classList.contains('hidden');setPublicModeV1202(!signedIn);if(signedIn)document.getElementById('mobileNav')?.classList.remove('hidden');else document.getElementById('mobileNav')?.classList.add('hidden')}

// ===== JWorks V12.1 · Growth + Implementation =====
const JW_VERSION_121='12.1.0';
const MIGRATION_SOURCES_121={
 monday:{name:'monday.com',format:'Excel (.xlsx)',hint:'Export each board to Excel. Include subitems/updates when useful; board views are not part of the export.'},
 asana:{name:'Asana',format:'CSV or JSON',hint:'Export projects as CSV/JSON. Start with CSV for guided mapping.'},
 clickup:{name:'ClickUp',format:'CSV / Excel',hint:'Export task data or a List/Table view with all columns.'},
 smartsheet:{name:'Smartsheet',format:'Excel (.xlsx)',hint:'Export sheets/reports to Excel. Formula behavior and some column types may require review.'},
 msproject:{name:'Microsoft Project',format:'XML / Excel',hint:'Use a structured task export; preserve task names, dates, hierarchy and dependencies where present.'},
 jira:{name:'Jira',format:'CSV',hint:'Export issues to CSV with key, summary, status, assignee, dates and parent/epic fields.'},
 trello:{name:'Trello',format:'CSV / JSON',hint:'Export board data and map lists to statuses or phases.'},
 excel:{name:'Excel / CSV',format:'XLSX / CSV',hint:'Use the JWorks templates or map your existing columns during preview.'}
};
function publicToolsV121(){setPublicModeV1202(true);let m=document.getElementById('marketing');m.classList.remove('hidden');let root=m.querySelector('.mcontent');root.innerHTML=`<section class="public-page-head"><div class="moverline">FREE PROJECT TOOLS</div><h1>Useful before you ever<br><em>create an account.</em></h1><p>Practical project-management tools built to turn messy inputs into something you can use.</p></section><section class="tool-grid121">${[['SOW Builder','Build a structured contractor scope and flag missing information.','sow'],['Meeting → Actions','Turn meeting notes into actions, decisions, risks and follow-ups.','meeting'],['Project Health Check','Score schedule, budget, ownership and delivery risk.','health'],['Status Report Builder','Turn rough updates into an executive-ready status summary.','status'],['Risk Register Starter','Create an initial risk register from project context.','risk'],['Project Charter Builder','Structure objectives, scope, stakeholders and success criteria.','charter'],['RACI Starter','Build an initial responsibility matrix.','raci'],['Milestone Planner','Turn a target outcome into major delivery milestones.','milestone'],['Change Request Builder','Document a proposed project change and its impacts.','change'],['Closeout Checklist','Generate a practical project closeout checklist.','closeout'],['Readiness Assessment','Check whether a project is actually ready to start.','ready'],['Lessons Learned','Turn project observations into reusable lessons.','lessons']].map(x=>`<article class="free-tool121"><span>FREE TOOL</span><h3>${x[0]}</h3><p>${x[1]}</p><button class="mghost" onclick="runFreeTool121('${x[2]}','${x[0]}')">Open Tool →</button></article>`).join('')}</section><section id="freeToolWorkbench121" class="tool-workbench121 hidden"></section><section class="finalcta"><h2>When the tool becomes a project,<br><em>bring it into JWorks.</em></h2><button class="mprimary big" onclick="showTrialV12()">Start Free Trial</button><button class="mghost big" onclick="location.reload()">Back to JWorks</button></section>`;scrollTo(0,0)}
function runFreeTool121(kind,name){let w=$('freeToolWorkbench121');w.classList.remove('hidden');w.innerHTML=`<div class="moverline">${esc(name).toUpperCase()}</div><h2>${esc(name)}</h2><p>Describe the project, situation or raw notes. JWorks will structure a useful starting point locally in your browser for this preview.</p><textarea id="freeInput121" placeholder="Paste notes or describe the project…"></textarea><div class="hero-actions"><button class="mprimary" onclick="generateFree121('${kind}')">Generate</button></div><div id="freeOutput121"></div>`;w.scrollIntoView({behavior:'smooth'})}
function generateFree121(kind){let t=val('freeInput121').trim();if(!t)return alert('Add some project context first.');let labels={sow:['Purpose / Outcome','Scope Requirements','Responsibilities','Access / Coordination','Testing & Closeout','Items to Confirm'],meeting:['Actions','Decisions','Risks / Issues','Follow-ups'],health:['Schedule','Budget','Scope','Ownership','Dependencies','Overall Attention'],status:['Executive Summary','Progress','Next Steps','Risks / Decisions'],risk:['Risk','Impact','Mitigation','Owner / Trigger'],charter:['Objective','In Scope','Out of Scope','Stakeholders','Success Criteria'],raci:['Workstream','Responsible','Accountable','Consulted','Informed'],milestone:['Initiation','Planning','Execution','Validation','Closeout'],change:['Requested Change','Reason','Schedule Impact','Cost Impact','Risk / Approval'],closeout:['Deliverables','Testing','Documentation','Training','Financial Close','Lessons Learned'],ready:['Scope','Owner','Budget','Schedule','Dependencies','Approvals'],lessons:['What Happened','Impact','What Worked','What to Change','Reusable Lesson']}[kind]||['Summary','Actions','Risks'];$('freeOutput121').innerHTML=`<div class="free-result121"><h3>JWorks starting point</h3>${labels.map((x,i)=>`<div><b>${x}</b><p>${i===0?esc(t.slice(0,420)):'Review and complete this section based on the project context. <strong>[TO CONFIRM]</strong>'}</p></div>`).join('')}<p class="small">This free preview structures your input; review all project-specific details before use.</p></div>`}
async function implementationCenterV121(){let r=await api('implementations');let items=r.items||[];$('main').innerHTML=title('JWorks Owner','Implementation Center','Onboard customers with a repeatable, low-touch implementation workflow.',btn('+ Implement Customer','newImplementationV121()','primary'))+`<div class="metrics"><div class="metric"><strong>${items.length}</strong><span>Implementations</span></div><div class="metric"><strong>${items.filter(x=>Number(x.progress)===100).length}</strong><span>Completed</span></div><div class="metric"><strong>${items.filter(x=>Number(x.progress)<100).length}</strong><span>In progress</span></div><div class="metric"><strong>${items.length?Math.round(items.reduce((a,x)=>a+Number(x.progress||0),0)/items.length):0}%</strong><span>Average progress</span></div></div><div class="grid"><div class="panel"><h2>Customer implementations</h2>${items.map(x=>`<div class="listrow"><div><b>${esc(x.company_name)}</b><div class="small muted">${esc(MIGRATION_SOURCES_121[x.source_platform]?.name||x.source_platform)} · ${x.progress}% complete</div><div class="licensebar" style="margin-top:7px"><i style="width:${x.progress}%"></i></div></div>${btn('Open',`openImplementationV121('${x.id}')`)}</div>`).join('')||'<div class="empty">No customer implementations yet.</div>'}</div><div class="panel"><h2>Implementation Packs</h2>${['Facilities & Maintenance','Capital Projects','Engineering','Construction','IT & Technology','General Project Management'].map(x=>`<div class="listrow"><div><b>${x}</b><div class="small muted">Reusable statuses, phases, workflows, reports and onboarding defaults.</div></div><span>Template</span></div>`).join('')}<h2 style="margin-top:22px">Migration Studio</h2><p class="muted">Guided presets for monday.com, Asana, ClickUp, Smartsheet, Microsoft Project, Jira, Trello and Excel/CSV.</p>${btn('Open Migration Guide','migrationStudioV121()','primary')}</div></div>`}
function newImplementationV121(){let opts=Object.entries(MIGRATION_SOURCES_121).map(([k,v])=>`<option value="${k}">${v.name}</option>`).join('');openModal('Implement Customer',`<div class="form"><label>Customer / company name<input id="implName121"></label><label>Source platform<select id="implSource121">${opts}</select></label></div>`,async()=>{await api('implementations','POST',{company_name:val('implName121'),source_platform:val('implSource121')});closeModal();implementationCenterV121()})}
async function openImplementationV121(id){let r=await api('implementations/'+id),x=r.item;$('main').innerHTML=title('Implementation',x.company_name,`${x.progress}% complete · ${MIGRATION_SOURCES_121[x.source_platform]?.name||x.source_platform}`)+`<div class="panel"><h2>Implementation path</h2>${r.steps.map(s=>`<div class="listrow"><div><b>${esc(s.title)}</b><div class="small muted">${esc(s.status)}</div></div><select onchange="updateImplStepV121('${id}','${s.id}',this.value)"><option value="pending" ${s.status==='pending'?'selected':''}>Pending</option><option value="in_progress" ${s.status==='in_progress'?'selected':''}>In progress</option><option value="done" ${s.status==='done'?'selected':''}>Done</option></select></div>`).join('')}</div><div class="grid"><div class="panel"><h2>Migration</h2><p>${esc(MIGRATION_SOURCES_121[x.source_platform]?.hint||'Prepare a structured export and validate it before import.')}</p>${btn('Open Migration Studio',`migrationStudioV121('${id}','${x.source_platform}')`,'primary')}</div><div class="panel"><h2>Low-touch onboarding</h2><p class="muted">Discovery → configuration → migration → users → validation → training → go-live → 30-day review.</p><p>Use the checklist as the customer record so onboarding does not live in email or memory.</p></div></div>`}
async function updateImplStepV121(id,sid,status){await api(`implementations/${id}/step/${sid}`,'PATCH',{status});await openImplementationV121(id)}
function migrationStudioV121(impl='',source='monday'){let cards=Object.entries(MIGRATION_SOURCES_121).map(([k,v])=>`<div class="setting-card ${k===source?'migration-selected121':''}"><b>${v.name}</b><div class="small muted">${v.format}</div><p>${v.hint}</p><button class="btn" onclick="migrationStudioV121('${impl}','${k}')">Use preset</button></div>`).join('');$('main').innerHTML=title('Implementation Center','Migration Studio','Export → map → validate → dry run → import. Never write customer data before review.')+`<div class="settings-grid">${cards}</div><div class="panel"><h2>${MIGRATION_SOURCES_121[source].name} migration workflow</h2><div class="migration-steps121"><b>1 · Export</b><span>${MIGRATION_SOURCES_121[source].hint}</span><b>2 · Upload</b><span>Use the existing JWorks Import Center for structured XLSX project/task imports.</span><b>3 · Map</b><span>Map source fields to JWorks project/task fields; save reusable customer mappings.</span><b>4 · Validate</b><span>Check missing project codes, users, dates, statuses, duplicates and unsupported fields.</span><b>5 · Dry Run</b><span>Show ready / review / cannot-import counts before any database changes.</span><b>6 · Import + Audit</b><span>Commit validated records and retain an implementation record.</span></div><div class="actions">${btn('Open Import Center',`page='importcenter';render()`,'primary')}${impl?btn('Back to Customer',`openImplementationV121('${impl}')`):''}</div></div>`}
const renderV121Base=render;render=function(){if(page==='implementation'){if(JW11?.session?.role!=='platform_owner'){page='dashboard';return renderV121Base()}return implementationCenterV121()}return renderV121Base()}
setTimeout(()=>{let n=$('implementationNav');if(n)n.classList.toggle('hidden',JW11?.session?.role!=='platform_owner')},1200);

// ===== JWorks V12.2 · Project Lab + Demo Workspace =====
const JW_VERSION_122='12.2.0';
const LAB_TOOLS_122=[
 ['BUILD','SOW Builder','sow','Turn rough requirements into a structured contractor scope.'],['BUILD','Project Charter','charter','Structure objectives, scope, stakeholders and success criteria.'],['BUILD','Status Report Builder','status','Create an executive-ready update from rough notes.'],['BUILD','Risk Register','risk','Turn project context into an initial risk register.'],['BUILD','RACI Builder','raci','Create a responsibility matrix for a project or workstream.'],['BUILD','Change Request','change','Document scope, schedule, cost and approval impacts.'],['BUILD','Closeout Checklist','closeout','Create a practical handover and closeout checklist.'],
 ['CALCULATE','Earned Value Calculator','evm','Calculate CPI, SPI, EAC, ETC and VAC.'],['CALCULATE','Contingency Calculator','contingency','Estimate a simple risk-based project reserve.'],['CALCULATE','Meeting Cost Calculator','meetingcost','See the real cost of recurring project meetings.'],['CALCULATE','Resource Capacity','capacity','Compare available team hours with planned demand.'],['CALCULATE','Change Impact Calculator','changeimpact','Estimate combined cost and schedule impact.'],
 ['ANALYZE','Project Rescue','rescue','Diagnose a troubled project and produce a recovery starting point.'],['ANALYZE','Schedule Health Check','schedule','Check dates, dependencies and overdue work.'],['ANALYZE','RFP / SOW Quality Check','sowcheck','Find missing contractor-scope information before issue.'],['ANALYZE','Bid Comparison','bid','Structure contractor bids for an apples-to-apples review.'],['ANALYZE','RAID Analyzer','raid','Review risks, assumptions, issues and decisions for gaps.'],['ANALYZE','Migration Readiness','migration','Assess an export before moving it into JWorks.'],
 ['ASSESS','Project Health Check','health','Score schedule, budget, scope, ownership and dependencies.'],['ASSESS','PM Maturity Assessment','maturity','Assess how consistently your organization manages projects.'],['ASSESS','Project Readiness','ready','Check whether a project is actually ready to start.'],['ASSESS','Handover Readiness','handover','Check documentation, training, testing and ownership.'],['AI','Meeting → Actions','meeting','Turn notes into actions, decisions, risks and follow-ups.'],['AI','Email → Actions','email','Extract project work from a messy email thread.'],['AI','Lessons Learned','lessons','Turn observations into reusable organizational learning.']
];
function projectLabV122(filter='ALL'){setPublicModeV1202(true);let m=$('marketing');m.classList.remove('hidden');let root=m.querySelector('.mcontent'),cats=['ALL','BUILD','CALCULATE','ANALYZE','ASSESS','AI'];let tools=filter==='ALL'?LAB_TOOLS_122:LAB_TOOLS_122.filter(x=>x[0]===filter);root.innerHTML=`<section class="public-page-head lab-head122"><div class="moverline">JWORKS PROJECT LAB</div><h1>Useful project tools.<br><em>No account required.</em></h1><p>Build, calculate, analyze and assess real project work—then bring the result into JWorks when you are ready.</p><div class="lab-filters122">${cats.map(c=>`<button class="${c===filter?'active':''}" onclick="projectLabV122('${c}')">${c}</button>`).join('')}</div></section><section class="tool-grid121">${tools.map(x=>`<article class="free-tool121"><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[3]}</p><button class="mghost" onclick="runLabToolV122('${x[2]}','${x[1]}')">Open Tool →</button></article>`).join('')}</section><section id="freeToolWorkbench121" class="tool-workbench121 hidden"></section><section class="finalcta"><h2>Less time maintaining the system.<br><em>More time managing the project.</em></h2><button class="mprimary big" onclick="showTrialV12()">Bring your project into JWorks</button></section>`;scrollTo(0,0)}
function runLabToolV122(kind,name){let w=$('freeToolWorkbench121');w.classList.remove('hidden');let calc=['evm','contingency','meetingcost','capacity','changeimpact'].includes(kind);w.innerHTML=`<div class="moverline">${esc(name).toUpperCase()}</div><h2>${esc(name)}</h2>${calc?labCalcFormV122(kind):`<p>Paste notes, project context or source information below. Do not include confidential information you are not authorized to process.</p><textarea id="freeInput121" placeholder="Describe the project or paste your working notes…"></textarea><div class="hero-actions"><button class="mprimary" onclick="generateLabV122('${kind}')">Analyze</button></div>`}<div id="freeOutput121"></div>`;w.scrollIntoView({behavior:'smooth'})}
function labCalcFormV122(k){let fields=k==='evm'?[['PV','Planned Value'],['EV','Earned Value'],['AC','Actual Cost'],['BAC','Budget at Completion']]:k==='meetingcost'?[['PEOPLE','Attendees'],['RATE','Average hourly loaded cost'],['HOURS','Meeting hours'],['FREQ','Meetings per year']]:k==='capacity'?[['PEOPLE','Team members'],['HOURS','Hours/person/week'],['UTIL','Target utilization %'],['DEMAND','Planned demand hours/week']]:k==='changeimpact'?[['BASE','Current budget'],['COST','Change cost'],['DAYS','Schedule days added'],['CONT','Contingency %']]:[['BUDGET','Project budget'],['LOW','Low-risk exposure'],['MED','Medium-risk exposure'],['HIGH','High-risk exposure']];return `<div class="lab-calc122">${fields.map(x=>`<label>${x[1]}<input id="lab${x[0]}" type="number" min="0" step="any"></label>`).join('')}</div><button class="mprimary" onclick="calculateLabV122('${k}')">Calculate</button>`}
function calculateLabV122(k){let n=id=>Number(val('lab'+id)||0),out='';if(k==='evm'){let pv=n('PV'),ev=n('EV'),ac=n('AC'),bac=n('BAC'),cpi=ac?ev/ac:0,spi=pv?ev/pv:0,eac=cpi?bac/cpi:0;out=`CPI <b>${cpi.toFixed(2)}</b> · SPI <b>${spi.toFixed(2)}</b> · EAC <b>$${Math.round(eac).toLocaleString()}</b> · ETC <b>$${Math.round(eac-ac).toLocaleString()}</b> · VAC <b>$${Math.round(bac-eac).toLocaleString()}</b>`}else if(k==='meetingcost'){out=`Estimated annual meeting cost: <b>$${Math.round(n('PEOPLE')*n('RATE')*n('HOURS')*n('FREQ')).toLocaleString()}</b>`}else if(k==='capacity'){let cap=n('PEOPLE')*n('HOURS')*(n('UTIL')/100);out=`Usable capacity: <b>${cap.toFixed(1)} h/week</b> · ${n('DEMAND')>cap?'<b>Over capacity by '+(n('DEMAND')-cap).toFixed(1)+' h/week</b>':'Capacity remaining: <b>'+(cap-n('DEMAND')).toFixed(1)+' h/week</b>'}`}else if(k==='changeimpact'){let c=n('COST')*(1+n('CONT')/100);out=`Adjusted change exposure: <b>$${Math.round(c).toLocaleString()}</b> · Revised budget: <b>$${Math.round(n('BASE')+c).toLocaleString()}</b> · Schedule impact: <b>${n('DAYS')} days</b>`}else{let reserve=n('LOW')*.1+n('MED')*.3+n('HIGH')*.6;out=`Risk-weighted reserve starting point: <b>$${Math.round(reserve).toLocaleString()}</b> · ${(n('BUDGET')?reserve/n('BUDGET')*100:0).toFixed(1)}% of budget`}$('freeOutput121').innerHTML=`<div class="free-result121"><h3>Result</h3><p>${out}</p><p class="small">Planning aid only. Validate assumptions before making project or financial decisions.</p></div>`}
function generateLabV122(kind){let t=val('freeInput121').trim();if(!t)return alert('Add some project context first.');if(kind==='rescue'){$('freeOutput121').innerHTML=`<div class="free-result121"><h3>Project Rescue · Initial diagnosis</h3><p><b>Attention level:</b> Needs review</p><div><b>What appears to be happening</b><p>${esc(t.slice(0,520))}</p></div><div><b>Recovery priorities</b><p>1. Confirm the critical outcome and next immovable milestone.<br>2. Identify overdue predecessors and assign one accountable owner to each.<br>3. Reconcile actual/forecast cost with remaining work.<br>4. Escalate unresolved approvals and high-impact risks.<br>5. Establish a short recovery cadence until the plan is credible.</p></div><p class="small">JWorks has not independently verified the supplied facts. Review before acting.</p></div>`;return}generateFree121(kind)}
async function demoWorkspaceV122(){let r=await api('demo-workspace');$('main').innerHTML=title('Company Portal','Demo Workspace','A resettable fictional portfolio for customer presentations.')+`<div class="panel demo-panel122"><div class="moverline">NORTHSTAR INDUSTRIES · FICTIONAL</div><h2>Presentation-ready JWorks workspace</h2><p>Eight connected fictional projects demonstrate healthy work, schedule pressure, budget pressure, approvals, procurement, risks, meetings and decisions. Demo records are tagged separately from normal company data.</p><div class="metrics"><div class="metric"><strong>${r.loaded?'READY':'EMPTY'}</strong><span>Demo status</span></div><div class="metric"><strong>${r.records||0}</strong><span>Tagged records</span></div><div class="metric"><strong>8</strong><span>Demo projects</span></div></div><div class="actions"><button class="btn primary" onclick="demoActionV122('${r.loaded?'reset':'load'}')">${r.loaded?'Reset Demo Workspace':'Load Demo Workspace'}</button>${r.loaded?'<button class="btn" onclick="presentationModeV122()">▶ Presentation Mode</button><button class="btn danger" onclick="demoActionV122(\'clear\')">Clear Demo Data</button>':''}</div><p class="small muted">Clear Demo Data deletes only records registered in the demo-record ledger. It does not select records by project name.</p></div>`}
async function demoActionV122(a){if(a==='clear'&&!confirm('Clear the tagged Northstar demo data? Normal JWorks records are not targeted.'))return;await api('demo-workspace/'+a,'POST',{});await demoWorkspaceV122()}
function presentationModeV122(){localStorage.setItem('jworks_presentation','1');page='dashboard';render();setTimeout(()=>alert('Presentation Mode\n\nSuggested story: Command Center → North Campus Expansion → Project Pulse → Roadmap → Approvals → Meeting Actions → Executive reporting.\n\nAll Northstar data is fictional.'),250)}
const renderV122Base=render;render=function(){if(page==='demoworkspace')return demoWorkspaceV122();return renderV122Base()}
